import * as THREE from 'three';

export const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
export const lerp = (a, b, t) => a + (b - a) * t;
export const damp = (a, b, lambda, dt) => b + (a - b) * Math.exp(-lambda * dt);
export const rand = (min, max) => min + Math.random() * (max - min);
export const randInt = (min, max) => Math.floor(rand(min, max + 1));
export const TAU = Math.PI * 2;

export function wrapAngle(angle) {
  return ((angle + Math.PI) % TAU + TAU) % TAU - Math.PI;
}

export function angleLerp(a, b, t) {
  return a + wrapAngle(b - a) * t;
}

export function smoothstep(edge0, edge1, value) {
  const t = clamp((value - edge0) / (edge1 - edge0), 0, 1);
  return t * t * (3 - 2 * t);
}

export function formatClock(seconds) {
  const total = Math.max(0, Math.floor(seconds));
  const minutes = Math.floor(total / 60);
  const rest = total % 60;
  return `${String(minutes).padStart(2, '0')}:${String(rest).padStart(2, '0')}`;
}

import * as THREE from 'three';
import { rand, TAU } from './utils.js';

function canvasTexture(width, height, draw, { repeat = null, anisotropy = 8 } = {}) {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');
  draw(ctx, width, height);
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.anisotropy = anisotropy;
  if (repeat) {
    texture.wrapS = THREE.RepeatWrapping;
    texture.wrapT = THREE.RepeatWrapping;
    texture.repeat.set(repeat[0], repeat[1]);
  }
  return texture;
}

export function makeFloorTexture(width = 64, length = 92) {
  const px = 16;
  return canvasTexture(width * px, length * px, (ctx, w, h) => {
    const cx = w / 2;
    const cy = h / 2;

    const base = ctx.createLinearGradient(0, 0, 0, h);
    base.addColorStop(0, '#160f13');
    base.addColorStop(0.16, '#0b1521');
    base.addColorStop(0.5, '#0a1422');
    base.addColorStop(0.84, '#0b1622');
    base.addColorStop(1, '#0d1a24');
    ctx.fillStyle = base;
    ctx.fillRect(0, 0, w, h);

    const glowTop = ctx.createRadialGradient(cx, 80, 20, cx, 80, 520);
    glowTop.addColorStop(0, 'rgba(255, 107, 61, 0.16)');
    glowTop.addColorStop(1, 'rgba(255, 107, 61, 0)');
    ctx.fillStyle = glowTop;
    ctx.fillRect(0, 0, w, h);

    const glowBottom = ctx.createRadialGradient(cx, h - 80, 20, cx, h - 80, 520);
    glowBottom.addColorStop(0, 'rgba(62, 233, 255, 0.14)');
    glowBottom.addColorStop(1, 'rgba(62, 233, 255, 0)');
    ctx.fillStyle = glowBottom;
    ctx.fillRect(0, 0, w, h);

    // fine tech grid
    ctx.strokeStyle = 'rgba(150, 205, 245, 0.06)';
    ctx.lineWidth = 1;
    for (let x = 0; x <= w; x += px * 2) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, h);
      ctx.stroke();
    }
    for (let y = 0; y <= h; y += px * 2) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(w, y);
      ctx.stroke();
    }

    // major panel grid
    ctx.strokeStyle = 'rgba(150, 205, 245, 0.075)';
    ctx.lineWidth = 2;
    for (let x = 0; x <= w; x += px * 8) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, h);
      ctx.stroke();
    }
    for (let y = 0; y <= h; y += px * 8) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(w, y);
      ctx.stroke();
    }

    // scattered floor speckles / wear
    for (let i = 0; i < 900; i += 1) {
      ctx.fillStyle = `rgba(180, 220, 255, ${rand(0.01, 0.05)})`;
      ctx.fillRect(rand(0, w), rand(0, h), rand(1, 3), rand(1, 3));
    }

    ctx.lineJoin = 'round';
    const line = (color, widthPx, blur = 0) => {
      ctx.strokeStyle = color;
      ctx.lineWidth = widthPx;
      ctx.shadowColor = color;
      ctx.shadowBlur = blur;
    };

    // outer boundary
    line('rgba(221, 245, 255, 0.55)', 5, 14);
    ctx.strokeRect(px * 1.4, px * 1.4, w - px * 2.8, h - px * 2.8);
    ctx.shadowBlur = 0;

    // halfway line
    line('rgba(210, 240, 255, 0.3)', 3, 8);
    ctx.beginPath();
    ctx.moveTo(px * 1.4, cy);
    ctx.lineTo(w - px * 1.4, cy);
    ctx.stroke();

    // center circle - split team colors
    const radius = px * 8;
    ctx.lineWidth = 5;
    ctx.shadowBlur = 18;
    ctx.strokeStyle = 'rgba(255, 107, 61, 0.9)';
    ctx.shadowColor = 'rgba(255, 107, 61, 0.9)';
    ctx.beginPath();
    ctx.arc(cx, cy, radius, Math.PI, TAU);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(62, 233, 255, 0.9)';
    ctx.shadowColor = 'rgba(62, 233, 255, 0.9)';
    ctx.beginPath();
    ctx.arc(cx, cy, radius, 0, Math.PI);
    ctx.stroke();

    ctx.fillStyle = 'rgba(235, 251, 255, 0.9)';
    ctx.shadowColor = 'rgba(180, 245, 255, 0.9)';
    ctx.beginPath();
    ctx.arc(cx, cy, px * 0.7, 0, TAU);
    ctx.fill();
    ctx.shadowBlur = 0;

    // center wordmark
    ctx.save();
    ctx.translate(cx, cy);
    ctx.fillStyle = 'rgba(190, 225, 245, 0.12)';
    ctx.font = 'italic 700 58px "Chakra Petch", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('ROCKET DUEL', 0, -px * 10.5);
    ctx.restore();

    // penalty boxes
    const boxW = px * 36;
    const boxD = px * 16;
    for (const top of [true, false]) {
      const color = top ? 'rgba(255, 107, 61, 0.7)' : 'rgba(62, 233, 255, 0.7)';
      line(color, 4, 10);
      const y = top ? px * 3 : h - px * 3 - boxD;
      ctx.beginPath();
      ctx.moveTo(cx - boxW / 2, y);
      ctx.lineTo(cx - boxW / 2, y + boxD);
      ctx.lineTo(cx + boxW / 2, y + boxD);
      ctx.lineTo(cx + boxW / 2, y);
      ctx.stroke();
      ctx.shadowBlur = 0;

      // goal crease arc
      const goalY = top ? px * 1.4 : h - px * 1.4;
      ctx.beginPath();
      ctx.strokeStyle = color;
      ctx.lineWidth = 3;
      ctx.shadowColor = color;
      ctx.shadowBlur = 10;
      ctx.arc(cx, goalY, px * 7, top ? -Math.PI / 2 : Math.PI / 2, top ? Math.PI / 2 : Math.PI * 1.5, top ? false : false);
      ctx.stroke();
      ctx.shadowBlur = 0;
    }

    // corner speed chevrons
    for (const [x, y, flip] of [[px * 4, px * 4, 1], [w - px * 4, px * 4, -1], [px * 4, h - px * 4, 1], [w - px * 4, h - px * 4, -1]]) {
      ctx.strokeStyle = 'rgba(160, 225, 255, 0.18)';
      ctx.lineWidth = 3;
      for (let i = 0; i < 4; i += 1) {
        ctx.beginPath();
        ctx.moveTo(x + flip * i * 14, y);
        ctx.lineTo(x + flip * (i * 14 + 26), y + 26);
        ctx.stroke();
      }
    }

    // end zone labels (readable from each goal looking in)
    ctx.save();
    ctx.translate(cx, px * 9.5);
    ctx.rotate(Math.PI);
    ctx.fillStyle = 'rgba(255, 107, 61, 0.1)';
    ctx.font = '900 96px "Chakra Petch", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('NOVA', 0, 0);
    ctx.restore();

    ctx.save();
    ctx.translate(cx, h - px * 9.5);
    ctx.fillStyle = 'rgba(62, 233, 255, 0.11)';
    ctx.font = '900 96px "Chakra Petch", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('YOU', 0, 0);
    ctx.restore();
  }, { anisotropy: 16 });
}

export function makePanelTexture() {
  return canvasTexture(256, 256, (ctx, w, h) => {
    const grad = ctx.createLinearGradient(0, 0, 0, h);
    grad.addColorStop(0, '#101c2c');
    grad.addColorStop(0.55, '#0a1320');
    grad.addColorStop(1, '#060c16');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);

    ctx.strokeStyle = 'rgba(150, 210, 255, 0.12)';
    ctx.lineWidth = 2;
    ctx.strokeRect(3, 3, w - 6, h - 6);
    ctx.strokeStyle = 'rgba(0, 0, 0, 0.35)';
    ctx.lineWidth = 3;
    for (let x = 64; x < w; x += 64) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, h);
      ctx.stroke();
    }
    ctx.strokeStyle = 'rgba(150, 210, 255, 0.06)';
    ctx.lineWidth = 1;
    for (let y = 32; y < h; y += 64) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(w, y);
      ctx.stroke();
    }
    for (let x = 14; x < w; x += 64) {
      for (const y of [14, h - 14]) {
        ctx.fillStyle = 'rgba(170, 225, 255, 0.24)';
        ctx.beginPath();
        ctx.arc(x, y, 1.6, 0, TAU);
        ctx.fill();
      }
    }
    for (let i = 0; i < 300; i += 1) {
      ctx.fillStyle = `rgba(200, 235, 255, ${rand(0.01, 0.04)})`;
      ctx.fillRect(rand(0, w), rand(0, h), 1, 1);
    }
  }, { repeat: [3, 3], anisotropy: 8 });
}

export function makeBallTexture() {
  return canvasTexture(1024, 512, (ctx, w, h) => {
    const base = ctx.createLinearGradient(0, 0, 0, h);
    base.addColorStop(0, '#e9eef3');
    base.addColorStop(0.45, '#f7f9fb');
    base.addColorStop(0.72, '#dfe6ec');
    base.addColorStop(1, '#eef2f6');
    ctx.fillStyle = base;
    ctx.fillRect(0, 0, w, h);

    const size = 46;
    const hexHeight = Math.sqrt(3) * size;
    const hexWidth = 2 * size;
    let col = 0;
    for (let y = -hexHeight; y < h + hexHeight; y += hexHeight * 0.5) {
      const rowOffset = (col % 2) * (hexWidth * 0.5);
      for (let x = -hexWidth; x < w + hexWidth; x += hexWidth) {
        const cx = x + rowOffset;
        const cy = y;
        ctx.beginPath();
        for (let i = 0; i < 6; i += 1) {
          const angle = (Math.PI / 3) * i;
          const px = cx + size * Math.cos(angle);
          const py = cy + hexHeight * 0.5 * Math.sin(angle) * 0.57735 * 1.732;
          if (i === 0) ctx.moveTo(px, py);
          else ctx.lineTo(px, py);
        }
        ctx.closePath();
        const seed = Math.abs(Math.sin(cx * 0.013 + cy * 0.021));
        if (seed > 0.86) {
          ctx.fillStyle = 'rgba(255, 107, 61, 0.5)';
          ctx.fill();
          ctx.strokeStyle = 'rgba(150, 45, 20, 0.35)';
        } else if (seed > 0.5) {
          ctx.fillStyle = 'rgba(214, 224, 233, 0.55)';
          ctx.fill();
          ctx.strokeStyle = 'rgba(48, 62, 78, 0.4)';
        } else {
          ctx.strokeStyle = 'rgba(46, 60, 76, 0.45)';
        }
        ctx.lineWidth = 3;
        ctx.stroke();
      }
      col += 1;
    }

    // tech seams
    ctx.strokeStyle = 'rgba(26, 40, 55, 0.5)';
    ctx.lineWidth = 7;
    ctx.beginPath();
    ctx.moveTo(0, h / 2);
    ctx.lineTo(w, h / 2);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(120, 235, 255, 0.35)';
    ctx.lineWidth = 2;
    ctx.setLineDash([12, 18]);
    ctx.beginPath();
    ctx.moveTo(0, h / 2);
    ctx.lineTo(w, h / 2);
    ctx.stroke();
    ctx.setLineDash([]);

    for (let i = 0; i < 200; i += 1) {
      ctx.fillStyle = `rgba(255, 255, 255, ${rand(0.02, 0.07)})`;
      ctx.fillRect(rand(0, w), rand(0, h), rand(1, 4), rand(1, 3));
    }

    // subtle vignettes at poles
    const pole = ctx.createLinearGradient(0, 0, 0, h);
    pole.addColorStop(0, 'rgba(30, 45, 60, 0.35)');
    pole.addColorStop(0.18, 'rgba(30, 45, 60, 0)');
    pole.addColorStop(0.82, 'rgba(30, 45, 60, 0)');
    pole.addColorStop(1, 'rgba(30, 45, 60, 0.35)');
    ctx.fillStyle = pole;
    ctx.fillRect(0, 0, w, h);
  }, { anisotropy: 8 });
}

export function makeNetTexture() {
  const texture = canvasTexture(256, 256, (ctx, w, h) => {
    ctx.clearRect(0, 0, w, h);
    ctx.strokeStyle = 'rgba(210, 240, 255, 0.65)';
    ctx.lineWidth = 1.4;
    for (let x = 0; x <= w; x += 22) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, h);
      ctx.stroke();
    }
    for (let y = 0; y <= h; y += 22) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(w, y);
      ctx.stroke();
    }
    ctx.strokeStyle = 'rgba(140, 200, 235, 0.2)';
    ctx.lineWidth = 1;
    for (let i = -h; i < w; i += 44) {
      ctx.beginPath();
      ctx.moveTo(i, 0);
      ctx.lineTo(i + h, h);
      ctx.stroke();
    }
  });
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  return texture;
}

export function makeBannerTexture(accent = '#3ee9ff', title = 'ROCKET DUEL', subtitle = '1V1 — FIRST TO 3') {
  return canvasTexture(1024, 256, (ctx, w, h) => {
    ctx.clearRect(0, 0, w, h);
    const grad = ctx.createLinearGradient(0, 0, w, 0);
    grad.addColorStop(0, 'rgba(4, 9, 17, 0)');
    grad.addColorStop(0.2, 'rgba(6, 13, 24, 0.85)');
    grad.addColorStop(0.8, 'rgba(6, 13, 24, 0.85)');
    grad.addColorStop(1, 'rgba(4, 9, 17, 0)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);

    ctx.fillStyle = accent;
    ctx.shadowColor = accent;
    ctx.shadowBlur = 30;
    ctx.fillRect(w * 0.22, h * 0.18, 5, h * 0.64);
    ctx.fillRect(w * 0.78 - 5, h * 0.18, 5, h * 0.64);

    ctx.shadowBlur = 34;
    ctx.fillStyle = '#f2fbff';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = 'italic 700 92px "Chakra Petch", sans-serif';
    ctx.fillText(title, w / 2, h * 0.44);

    ctx.shadowBlur = 18;
    ctx.fillStyle = accent;
    ctx.font = '600 30px "Chakra Petch", sans-serif';
    ctx.fillText(subtitle, w / 2, h * 0.72);

    ctx.shadowBlur = 0;
    ctx.strokeStyle = accent;
    ctx.globalAlpha = 0.55;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(w * 0.22, h * 0.18);
    ctx.lineTo(w * 0.78, h * 0.18);
    ctx.moveTo(w * 0.22, h * 0.82);
    ctx.lineTo(w * 0.78, h * 0.82);
    ctx.stroke();
  }, { anisotropy: 8 });
}

export function makeGlowTexture() {
  const texture = canvasTexture(128, 128, (ctx, w, h) => {
    const grad = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
    grad.addColorStop(0, 'rgba(255, 255, 255, 1)');
    grad.addColorStop(0.24, 'rgba(255, 255, 255, 0.75)');
    grad.addColorStop(0.55, 'rgba(255, 255, 255, 0.18)');
    grad.addColorStop(1, 'rgba(255, 255, 255, 0)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);
  }, { anisotropy: 1 });
  texture.colorSpace = THREE.NoColorSpace;
  return texture;
}

export function makeHaloTexture() {
  const texture = canvasTexture(256, 256, (ctx, w, h) => {
    const grad = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
    grad.addColorStop(0, 'rgba(255, 255, 255, 0.9)');
    grad.addColorStop(0.12, 'rgba(200, 250, 255, 0.55)');
    grad.addColorStop(0.4, 'rgba(110, 225, 255, 0.12)');
    grad.addColorStop(1, 'rgba(80, 200, 255, 0)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);
  }, { anisotropy: 2 });
  texture.colorSpace = THREE.NoColorSpace;
  return texture;
}

import * as THREE from 'three';

const VERTEX_SHADER = /* glsl */`
  attribute float aSize;
  attribute float aAlpha;
  attribute vec3 aColor;
  varying vec3 vColor;
  varying float vAlpha;
  void main() {
    vColor = aColor;
    vAlpha = aAlpha;
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_PointSize = min(96.0, aSize * (300.0 / max(1.0, -mv.z)));
    gl_Position = projectionMatrix * mv;
  }
`;

const FRAGMENT_SHADER = /* glsl */`
  uniform sampler2D uMap;
  varying vec3 vColor;
  varying float vAlpha;
  void main() {
    vec4 tex = texture2D(uMap, gl_PointCoord);
    float alpha = tex.a * vAlpha;
    if (alpha < 0.004) discard;
    gl_FragColor = vec4(vColor * tex.rgb, alpha);
  }
`;

export class ParticleField {
  constructor(scene, glowTexture, capacity = 2600) {
    this.capacity = capacity;
    this.particles = new Array(capacity);
    for (let i = 0; i < capacity; i += 1) {
      this.particles[i] = {
        active: false,
        pos: new THREE.Vector3(),
        vel: new THREE.Vector3(),
        life: 0,
        maxLife: 1,
        size: 1,
        color: new THREE.Color(),
        gravity: 0,
        drag: 0,
        fade: 1,
        grow: 0,
        swirl: 0,
      };
    }
    this.cursor = 0;

    this.positions = new Float32Array(capacity * 3);
    this.colors = new Float32Array(capacity * 3);
    this.sizes = new Float32Array(capacity);
    this.alphas = new Float32Array(capacity);
    for (let i = 0; i < capacity; i += 1) {
      this.alphas[i] = 0;
      this.sizes[i] = 0;
    }

    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.BufferAttribute(this.positions, 3).setUsage(THREE.DynamicDrawUsage));
    geometry.setAttribute('aColor', new THREE.BufferAttribute(this.colors, 3).setUsage(THREE.DynamicDrawUsage));
    geometry.setAttribute('aSize', new THREE.BufferAttribute(this.sizes, 1).setUsage(THREE.DynamicDrawUsage));
    geometry.setAttribute('aAlpha', new THREE.BufferAttribute(this.alphas, 1).setUsage(THREE.DynamicDrawUsage));
    geometry.boundingSphere = new THREE.Sphere(new THREE.Vector3(), 500);

    this.material = new THREE.ShaderMaterial({
      uniforms: { uMap: { value: glowTexture } },
      vertexShader: VERTEX_SHADER,
      fragmentShader: FRAGMENT_SHADER,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    });

    this.points = new THREE.Points(geometry, this.material);
    this.points.frustumCulled = false;
    this.points.renderOrder = 5;
    scene.add(this.points);
    this.geometry = geometry;
    this.dirty = true;
  }

  spawn({ position, velocity, color, size = 1, life = 1, gravity = 0, drag = 0, fade = 1, grow = 0, swirl = 0 }) {
    const p = this.particles[this.cursor];
    this.cursor = (this.cursor + 1) % this.capacity;
    p.active = true;
    p.pos.copy(position);
    if (velocity) p.vel.copy(velocity); else p.vel.set(0, 0, 0);
    p.life = life;
    p.maxLife = life;
    p.size = size;
    p.color.copy(color);
    p.gravity = gravity;
    p.drag = drag;
    p.fade = fade;
    p.grow = grow;
    p.swirl = swirl;
  }

  burst(position, count, { color, speed = 8, size = 1, life = 1, gravity = 10, drag = 1.4, spread = 1, fade = 1, grow = 0 }) {
    const base = color instanceof THREE.Color ? color : new THREE.Color(color);
    const tint = new THREE.Color();
    for (let i = 0; i < count; i += 1) {
      const dir = new THREE.Vector3(
        Math.random() * 2 - 1,
        Math.random() * 2 - 1,
        Math.random() * 2 - 1
      ).normalize().multiplyScalar(speed * (0.35 + Math.random() * 0.9));
      dir.x *= spread;
      tint.copy(base).offsetHSL((Math.random() - 0.5) * 0.05, 0, (Math.random() - 0.5) * 0.18);
      this.spawn({
        position,
        velocity: dir,
        color: tint,
        size: size * (0.55 + Math.random() * 0.9),
        life: life * (0.55 + Math.random() * 0.8),
        gravity,
        drag,
        fade,
        grow,
      });
    }
  }

  update(dt) {
    const { positions, colors, sizes, alphas } = this;
    const tempColor = new THREE.Color();
    for (let i = 0; i < this.capacity; i += 1) {
      const p = this.particles[i];
      const i3 = i * 3;
      if (!p.active) {
        alphas[i] = 0;
        sizes[i] = 0;
        continue;
      }
      p.life -= dt;
      if (p.life <= 0) {
        p.active = false;
        alphas[i] = 0;
        sizes[i] = 0;
        continue;
      }
      p.vel.y -= p.gravity * dt;
      p.vel.multiplyScalar(Math.max(0, 1 - p.drag * dt));
      if (p.swirl) {
        const angle = p.swirl * dt;
        const cos = Math.cos(angle);
        const sin = Math.sin(angle);
        const vx = p.vel.x * cos - p.vel.z * sin;
        const vz = p.vel.x * sin + p.vel.z * cos;
        p.vel.x = vx;
        p.vel.z = vz;
      }
      p.pos.addScaledVector(p.vel, dt);
      if (p.pos.y < 0.05) {
        p.pos.y = 0.05;
        p.vel.y *= -0.25;
        p.vel.x *= 0.8;
        p.vel.z *= 0.8;
      }
      const t = p.life / p.maxLife;
      positions[i3] = p.pos.x;
      positions[i3 + 1] = p.pos.y;
      positions[i3 + 2] = p.pos.z;
      tempColor.copy(p.color);
      colors[i3] = tempColor.r;
      colors[i3 + 1] = tempColor.g;
      colors[i3 + 2] = tempColor.b;
      sizes[i] = p.size * (1 + p.grow * (1 - t));
      alphas[i] = Math.pow(t, p.fade);
    }
    this.geometry.attributes.position.needsUpdate = true;
    this.geometry.attributes.aColor.needsUpdate = true;
    this.geometry.attributes.aSize.needsUpdate = true;
    this.geometry.attributes.aAlpha.needsUpdate = true;
  }
}

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.engine = null;
    this.ambience = null;
    this.boostGain = null;
    this.boostFilter = null;
    this.noiseBuffer = null;
    this.ready = false;
  }

  async init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') await this.ctx.resume().catch(() => {});
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    const ctx = new Ctx();
    this.ctx = ctx;

    const limiter = ctx.createDynamicsCompressor();
    limiter.threshold.value = -16;
    limiter.knee.value = 20;
    limiter.ratio.value = 7;
    limiter.attack.value = 0.004;
    limiter.release.value = 0.24;
    limiter.connect(ctx.destination);

    this.master = ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.56;
    this.master.connect(limiter);

    const seconds = 2.5;
    const buffer = ctx.createBuffer(1, Math.floor(ctx.sampleRate * seconds), ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < data.length; i += 1) {
      const white = Math.random() * 2 - 1;
      last = last * 0.72 + white * 0.28;
      data[i] = last;
    }
    this.noiseBuffer = buffer;

    this.buildAmbience();
    this.buildEngine();

    if (ctx.state === 'suspended') await ctx.resume().catch(() => {});
    this.ready = true;
  }

  buildAmbience() {
    const ctx = this.ctx;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = true;

    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = 480;
    filter.Q.value = 0.45;

    const gain = ctx.createGain();
    gain.gain.value = 0.035;

    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.11;
    const lfoGain = ctx.createGain();
    lfoGain.gain.value = 0.012;
    lfo.connect(lfoGain).connect(gain.gain);

    src.connect(filter).connect(gain).connect(this.master);
    src.start();
    lfo.start();
    this.ambience = { src, gain };
  }

  buildEngine() {
    const ctx = this.ctx;
    const oscA = ctx.createOscillator();
    oscA.type = 'sawtooth';
    oscA.frequency.value = 54;
    const oscB = ctx.createOscillator();
    oscB.type = 'square';
    oscB.frequency.value = 81;
    oscB.detune.value = -7;

    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 420;
    filter.Q.value = 2.2;

    const gain = ctx.createGain();
    gain.gain.value = 0.0001;

    oscA.connect(filter);
    oscB.connect(filter);
    filter.connect(gain).connect(this.master);
    oscA.start();
    oscB.start();
    this.engine = { oscA, oscB, filter, gain };

    const noise = ctx.createBufferSource();
    noise.buffer = this.noiseBuffer;
    noise.loop = true;
    const boostFilter = ctx.createBiquadFilter();
    boostFilter.type = 'bandpass';
    boostFilter.frequency.value = 1700;
    boostFilter.Q.value = 0.75;
    const boostGain = ctx.createGain();
    boostGain.gain.value = 0.0001;
    noise.connect(boostFilter).connect(boostGain).connect(this.master);
    noise.start();
    this.boostFilter = boostFilter;
    this.boostGain = boostGain;
  }

  setMuted(muted) {
    this.muted = muted;
    if (!this.ctx) return;
    this.master.gain.setTargetAtTime(muted ? 0 : 0.56, this.ctx.currentTime, 0.08);
  }

  updateEngine(speed, throttle, boosting, grounded, dt) {
    if (!this.engine) return;
    const t = this.ctx.currentTime;
    const s = Math.min(1, Math.abs(speed) / 46);
    const targetFreq = 48 + s * 128 + (boosting ? 16 : 0);
    this.engine.oscA.frequency.setTargetAtTime(targetFreq, t, 0.07);
    this.engine.oscB.frequency.setTargetAtTime(targetFreq * 1.501, t, 0.07);
    this.engine.filter.frequency.setTargetAtTime(330 + s * 1150 + (boosting ? 420 : 0), t, 0.1);
    const targetGain = 0.016 + s * 0.045 + Math.abs(throttle) * 0.012;
    this.engine.gain.gain.setTargetAtTime(targetGain, t, 0.09);
    if (this.boostGain) {
      this.boostGain.gain.setTargetAtTime(boosting ? 0.075 : 0.0001, t, 0.06);
      this.boostFilter.frequency.setTargetAtTime(boosting ? 2200 : 1500, t, 0.1);
    }
  }

  noiseBurst({ duration = 0.2, freq = 900, q = 1, gain = 0.2, type = 'bandpass', attack = 0.005, when = 0 }) {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const start = ctx.currentTime + when;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const filter = ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.setValueAtTime(freq, start);
    filter.Q.value = q;
    const env = ctx.createGain();
    env.gain.setValueAtTime(0.0001, start);
    env.gain.exponentialRampToValueAtTime(gain, start + attack);
    env.gain.exponentialRampToValueAtTime(0.0001, start + duration);
    src.connect(filter).connect(env).connect(this.master);
    src.start(start);
    src.stop(start + duration + 0.05);
  }

  tone({ freq = 220, duration = 0.2, type = 'sine', gain = 0.15, slide = 0, when = 0, filter = 0 }) {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const start = ctx.currentTime + when;
    const osc = ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, start);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), start + duration);
    const env = ctx.createGain();
    env.gain.setValueAtTime(0.0001, start);
    env.gain.exponentialRampToValueAtTime(gain, start + 0.008);
    env.gain.exponentialRampToValueAtTime(0.0001, start + duration);
    let node = osc;
    if (filter) {
      const f = ctx.createBiquadFilter();
      f.type = 'lowpass';
      f.frequency.value = filter;
      osc.connect(f);
      node = f;
    }
    node.connect(env).connect(this.master);
    osc.start(start);
    osc.stop(start + duration + 0.05);
  }

  playHit(strength = 1) {
    const s = Math.min(1.6, strength);
    this.noiseBurst({ duration: 0.16, freq: 520 + s * 500, q: 1.2, gain: 0.1 + s * 0.16, type: 'bandpass' });
    this.tone({ freq: 95 + s * 30, duration: 0.2, type: 'sine', gain: 0.16 + s * 0.14, slide: -55 });
    this.tone({ freq: 240 + s * 60, duration: 0.09, type: 'triangle', gain: 0.05 + s * 0.06, slide: 90 });
  }

  playWall(strength = 1) {
    this.tone({ freq: 84, duration: 0.18, type: 'sine', gain: 0.08 + Math.min(0.1, strength * 0.02), slide: -30 });
    this.noiseBurst({ duration: 0.12, freq: 320, q: 2, gain: 0.05, type: 'lowpass' });
  }

  playJump() {
    this.noiseBurst({ duration: 0.2, freq: 1100, q: 0.8, gain: 0.07, type: 'bandpass' });
    this.tone({ freq: 190, duration: 0.14, type: 'triangle', gain: 0.05, slide: 170 });
  }

  playDoubleJump() {
    this.noiseBurst({ duration: 0.26, freq: 1800, q: 0.7, gain: 0.08 });
    this.tone({ freq: 320, duration: 0.18, type: 'sawtooth', gain: 0.035, slide: 240, filter: 1400 });
  }

  playBoostStart() {
    this.noiseBurst({ duration: 0.3, freq: 2600, q: 0.6, gain: 0.09, attack: 0.01 });
  }

  playPickup(big) {
    this.tone({ freq: big ? 660 : 880, duration: 0.12, type: 'sine', gain: 0.06, slide: big ? 440 : 220 });
    this.tone({ freq: big ? 990 : 1320, duration: 0.14, type: 'triangle', gain: 0.035, when: 0.06 });
  }

  playCountdown(go) {
    this.tone({ freq: go ? 880 : 440, duration: go ? 0.5 : 0.13, type: 'square', gain: 0.045, filter: 2200 });
    if (go) this.tone({ freq: 1320, duration: 0.4, type: 'triangle', gain: 0.03, when: 0.04 });
  }

  playGoal(playerScored) {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const start = ctx.currentTime;
    const notes = playerScored ? [130.81, 164.81, 196, 261.63] : [110, 130.81, 146.83, 110];
    notes.forEach((freq, index) => {
      const osc = ctx.createOscillator();
      osc.type = index === notes.length - 1 ? 'sawtooth' : 'square';
      osc.frequency.value = freq;
      const filter = ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.value = 1400;
      const env = ctx.createGain();
      const at = start + index * 0.03;
      env.gain.setValueAtTime(0.0001, at);
      env.gain.exponentialRampToValueAtTime(0.06, at + 0.03);
      env.gain.setValueAtTime(0.06, at + 0.5);
      env.gain.exponentialRampToValueAtTime(0.0001, at + 1.4);
      osc.connect(filter).connect(env).connect(this.master);
      osc.start(at);
      osc.stop(at + 1.5);
    });
    this.noiseBurst({ duration: 1.4, freq: 900, q: 0.4, gain: 0.12, attack: 0.25, type: 'bandpass' });
    if (playerScored) {
      this.tone({ freq: 523.25, duration: 0.5, type: 'triangle', gain: 0.05, slide: 523.25, when: 0.1 });
    }
  }

  playWhistle() {
    this.tone({ freq: 2100, duration: 0.34, type: 'sine', gain: 0.05, slide: 260 });
    this.noiseBurst({ duration: 0.28, freq: 2400, q: 3, gain: 0.04 });
  }

  playWin(won) {
    const notes = won ? [523.25, 659.25, 783.99, 1046.5] : [392, 349.23, 311.13, 261.63];
    notes.forEach((freq, index) => {
      this.tone({ freq, duration: 0.35, type: 'triangle', gain: 0.055, when: index * 0.13, filter: 3200 });
    });
  }
}

const DEADZONE = 0.14;

function applyDeadzone(value) {
  return Math.abs(value) < DEADZONE ? 0 : value;
}

export class InputManager {
  constructor({ onPause, onMute, onRestart }) {
    this.keys = new Set();
    this.touch = { steer: 0, throttle: 0, jump: false, boost: false };
    this.joystickPointer = null;
    this.joystickCenter = { x: 0, y: 0 };
    this.gamepadPause = false;
    this.onPause = onPause;
    this.onMute = onMute;
    this.onRestart = onRestart;
    this.hasTouch = false;

    this.bindKeyboard();
    this.bindTouch();
    this.detectTouch();
  }

  detectTouch() {
    const coarse = window.matchMedia?.('(pointer: coarse)').matches;
    this.hasTouch = coarse || ('ontouchstart' in window && navigator.maxTouchPoints > 0);
    document.body.classList.toggle('touch', this.hasTouch);
  }

  bindKeyboard() {
    window.addEventListener('keydown', (event) => {
      if (event.repeat) {
        if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(event.code)) event.preventDefault();
        return;
      }
      this.keys.add(event.code);
      if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'ShiftLeft', 'ShiftRight'].includes(event.code)) {
        event.preventDefault();
      }
      if (event.code === 'Escape' || event.code === 'KeyP') this.onPause?.();
      if (event.code === 'KeyM') this.onMute?.();
      if (event.code === 'KeyR') this.onRestart?.();
    }, { passive: false });

    window.addEventListener('keyup', (event) => {
      this.keys.delete(event.code);
    });

    window.addEventListener('blur', () => {
      this.keys.clear();
      this.touch.jump = false;
      this.touch.boost = false;
    });
  }

  bindTouch() {
    const joystick = document.getElementById('joystick');
    const knob = document.getElementById('joystick-knob');
    const jump = document.getElementById('btn-jump');
    const boost = document.getElementById('btn-boost');
    if (!joystick || !knob || !jump || !boost) return;

    const setKnob = (dx, dy) => {
      knob.style.transform = `translate(${dx}px, ${dy}px)`;
    };

    const updateFromPointer = (event) => {
      let dx = event.clientX - this.joystickCenter.x;
      let dy = event.clientY - this.joystickCenter.y;
      const max = 42;
      const length = Math.hypot(dx, dy);
      if (length > max) {
        dx = dx / length * max;
        dy = dy / length * max;
      }
      setKnob(dx, dy);
      this.touch.steer = applyDeadzone(-dx / max);
      this.touch.throttle = applyDeadzone(-dy / max);
    };

    joystick.addEventListener('pointerdown', (event) => {
      event.preventDefault();
      this.joystickPointer = event.pointerId;
      const rect = joystick.getBoundingClientRect();
      this.joystickCenter = { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
      joystick.setPointerCapture(event.pointerId);
      updateFromPointer(event);
    });

    joystick.addEventListener('pointermove', (event) => {
      if (event.pointerId !== this.joystickPointer) return;
      updateFromPointer(event);
    });

    const release = (event) => {
      if (event.pointerId !== this.joystickPointer) return;
      this.joystickPointer = null;
      this.touch.steer = 0;
      this.touch.throttle = 0;
      setKnob(0, 0);
    };
    joystick.addEventListener('pointerup', release);
    joystick.addEventListener('pointercancel', release);
    joystick.addEventListener('lostpointercapture', release);

    const bindButton = (element, key) => {
      const press = (event) => {
        event.preventDefault();
        element.classList.add('pressed');
        this.touch[key] = true;
      };
      const releaseButton = (event) => {
        event.preventDefault();
        element.classList.remove('pressed');
        this.touch[key] = false;
      };
      element.addEventListener('pointerdown', press);
      element.addEventListener('pointerup', releaseButton);
      element.addEventListener('pointercancel', releaseButton);
      element.addEventListener('pointerleave', (event) => {
        if (event.buttons === 0) releaseButton(event);
      });
      element.addEventListener('contextmenu', (event) => event.preventDefault());
    };
    bindButton(jump, 'jump');
    bindButton(boost, 'boost');
  }

  snapshot() {
    let throttle = 0;
    let steer = 0;
    let jump = false;
    let boost = false;
    let handbrake = false;

    const keys = this.keys;
    if (keys.has('KeyW') || keys.has('ArrowUp')) throttle += 1;
    if (keys.has('KeyS') || keys.has('ArrowDown')) throttle -= 1;
    if (keys.has('KeyA') || keys.has('ArrowLeft')) steer += 1;
    if (keys.has('KeyD') || keys.has('ArrowRight')) steer -= 1;
    if (keys.has('Space')) jump = true;
    if (keys.has('ShiftLeft') || keys.has('ShiftRight')) boost = true;
    if (keys.has('KeyX') || keys.has('ControlLeft') || keys.has('ControlRight')) handbrake = true;

    if (this.touch.steer || this.touch.throttle) {
      steer = this.touch.steer;
      throttle = this.touch.throttle;
    }
    jump = jump || this.touch.jump;
    boost = boost || this.touch.boost;

    const pads = navigator.getGamepads?.() || [];
    for (const pad of pads) {
      if (!pad) continue;
      const axisX = applyDeadzone(pad.axes[0] || 0);
      const axisY = applyDeadzone(pad.axes[1] || 0);
      if (axisX || axisY) {
        steer = -axisX;
        throttle = -axisY;
      }
      if (pad.buttons[0]?.pressed) jump = true;
      if (pad.buttons[1]?.pressed || pad.buttons[7]?.pressed) boost = true;
      if (pad.buttons[2]?.pressed) handbrake = true;
      const start = Boolean(pad.buttons[9]?.pressed);
      if (start && !this.gamepadPause) this.onPause?.();
      this.gamepadPause = start;
    }

    return {
      throttle: Math.max(-1, Math.min(1, throttle)),
      steer: Math.max(-1, Math.min(1, steer)),
      jump,
      boost,
      handbrake,
    };
  }
}

import * as THREE from 'three';
import {
  makeFloorTexture,
  makePanelTexture,
  makeNetTexture,
  makeBannerTexture,
  makeHaloTexture,
} from './textures.js';
import { rand, TAU } from './utils.js';

export const ARENA = {
  width: 64,
  length: 92,
  wallHeight: 15.5,
  glassStart: 5.2,
  goalWidth: 20,
  goalHeight: 9,
  goalDepth: 9,
  ceiling: 19,
};

const YOU = 0x3ee9ff;
const BOT = 0xff6b3d;

function makeBox(width, height, depth, material, x, y, z, { cast = false, receive = true } = {}) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(width, height, depth), material);
  mesh.position.set(x, y, z);
  mesh.castShadow = cast;
  mesh.receiveShadow = receive;
  return mesh;
}

export class Arena {
  constructor(scene, glowTexture) {
    this.scene = scene;
    this.group = new THREE.Group();
    this.group.name = 'arena';
    scene.add(this.group);
    this.time = 0;
    this.pads = [];
    this.lights = [];
    this.glowTexture = glowTexture;
    this.haloTexture = makeHaloTexture();
    this.goalHalos = [];
    this.padGlowMaterial = null;

    this.buildMaterials();
    this.buildFloor();
    this.buildWalls();
    this.buildGoals();
    this.buildStands();
    this.buildCeiling();
    this.buildLights();
    this.buildPads();
  }

  buildMaterials() {
    this.floorMaterial = new THREE.MeshStandardMaterial({
      map: makeFloorTexture(ARENA.width, ARENA.length),
      roughness: 0.38,
      metalness: 0.36,
      envMapIntensity: 0.7,
    });
    this.wallMaterial = new THREE.MeshStandardMaterial({
      map: makePanelTexture(),
      color: 0x9fb8cc,
      roughness: 0.42,
      metalness: 0.68,
      envMapIntensity: 0.65,
    });
    this.frameMaterial = new THREE.MeshStandardMaterial({
      color: 0x182636,
      roughness: 0.3,
      metalness: 0.92,
      envMapIntensity: 0.9,
    });
    this.darkMaterial = new THREE.MeshStandardMaterial({
      color: 0x060c15,
      roughness: 0.6,
      metalness: 0.45,
    });
    this.glassMaterial = new THREE.MeshPhysicalMaterial({
      color: 0x8fdcff,
      roughness: 0.08,
      metalness: 0.1,
      transparent: true,
      opacity: 0.075,
      side: THREE.DoubleSide,
      depthWrite: false,
      envMapIntensity: 1.3,
    });
    this.netTexture = makeNetTexture();
    this.netMaterial = new THREE.MeshBasicMaterial({
      map: this.netTexture,
      color: 0xc8ecff,
      transparent: true,
      opacity: 0.72,
      side: THREE.DoubleSide,
      depthWrite: false,
    });
    this.crowdMaterial = new THREE.MeshStandardMaterial({
      roughness: 0.82,
      metalness: 0.05,
    });
    this.lightBankMaterial = new THREE.MeshStandardMaterial({
      color: 0xffffff,
      emissive: 0xdaf5ff,
      emissiveIntensity: 4,
      toneMapped: true,
    });
    this.youEmissive = new THREE.MeshStandardMaterial({
      color: 0x08303a,
      emissive: YOU,
      emissiveIntensity: 2.6,
      roughness: 0.35,
      metalness: 0.4,
    });
    this.botEmissive = new THREE.MeshStandardMaterial({
      color: 0x2a120a,
      emissive: BOT,
      emissiveIntensity: 2.6,
      roughness: 0.35,
      metalness: 0.4,
    });
    this.padMaterial = new THREE.MeshBasicMaterial({
      color: 0xffc35e,
      transparent: true,
      opacity: 0.9,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
    });
  }

  buildFloor() {
    const floor = new THREE.Mesh(
      new THREE.PlaneGeometry(ARENA.width, ARENA.length),
      this.floorMaterial
    );
    floor.rotation.x = -Math.PI / 2;
    floor.receiveShadow = true;
    this.group.add(floor);

    // Glow strips around the pitch perimeter.
    const edgeYou = new THREE.Mesh(new THREE.BoxGeometry(ARENA.width - 0.8, 0.1, 0.35), this.youEmissive);
    edgeYou.position.set(0, 0.055, ARENA.length / 2 - 1.4);
    this.group.add(edgeYou);
    const edgeBot = new THREE.Mesh(new THREE.BoxGeometry(ARENA.width - 0.8, 0.1, 0.35), this.botEmissive);
    edgeBot.position.set(0, 0.055, -ARENA.length / 2 + 1.4);
    this.group.add(edgeBot);

    const underglow = new THREE.Mesh(
      new THREE.PlaneGeometry(ARENA.width + 26, ARENA.length + 24),
      new THREE.MeshBasicMaterial({ color: 0x061220 })
    );
    underglow.rotation.x = -Math.PI / 2;
    underglow.position.y = -0.08;
    this.group.add(underglow);
  }

  buildWalls() {
    const { width, length, wallHeight, glassStart, goalWidth, goalHeight } = ARENA;
    const glassHeight = wallHeight - glassStart;

    for (const side of [-1, 1]) {
      const x = side * (width / 2 + 0.3);
      const base = makeBox(0.6, glassStart, length, this.wallMaterial, x, glassStart / 2, 0);
      this.group.add(base);

      const glass = new THREE.Mesh(new THREE.PlaneGeometry(length, glassHeight), this.glassMaterial);
      glass.rotation.y = side > 0 ? -Math.PI / 2 : Math.PI / 2;
      glass.position.set(x, glassStart + glassHeight / 2, 0);
      glass.renderOrder = 2;
      this.group.add(glass);

      const mullionCount = 12;
      for (let i = 0; i <= mullionCount; i += 1) {
        const z = -length / 2 + (length / mullionCount) * i;
        const mullion = makeBox(0.16, glassHeight, 0.16, this.frameMaterial, x, glassStart + glassHeight / 2, z);
        this.group.add(mullion);
      }

      // Rail lighting: cyan on the player's half, orange on NOVA's half.
      for (const [color, z, half] of [
        [this.youEmissive, length / 4, length / 2],
        [this.botEmissive, -length / 4, length / 2],
      ]) {
        const rail = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.14, half - 1), color);
        rail.position.set(x - side * 0.32, glassStart + 0.08, z);
        this.group.add(rail);
      }

      const topRail = makeBox(0.7, 0.34, length, this.frameMaterial, x, wallHeight + 0.1, 0);
      this.group.add(topRail);
      const topGlow = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.1, length - 2), this.lightBankMaterial);
      topGlow.position.set(x - side * 0.36, wallHeight + 0.12, 0);
      this.group.add(topGlow);
    }

    // End walls with the goal openings left open.
    for (const end of [-1, 1]) {
      const z = end * (length / 2 + 0.3);
      const segWidth = (width - goalWidth) / 2;
      const cyanSide = end > 0;
      for (const side of [-1, 1]) {
        const x = side * (goalWidth / 2 + segWidth / 2);
        const wall = makeBox(segWidth, wallHeight, 0.6, this.wallMaterial, x, wallHeight / 2, z);
        this.group.add(wall);
        const vertical = new THREE.Mesh(
          new THREE.BoxGeometry(0.16, wallHeight - 1.6, 0.12),
          cyanSide ? this.youEmissive : this.botEmissive
        );
        vertical.position.set(side * (goalWidth / 2 + 0.45), wallHeight / 2, z - end * 0.34);
        this.group.add(vertical);
      }

      const lintelHeight = wallHeight - goalHeight;
      const lintel = makeBox(goalWidth, lintelHeight, 0.7, this.wallMaterial, 0, goalHeight + lintelHeight / 2, z);
      this.group.add(lintel);

      const trim = new THREE.Mesh(
        new THREE.BoxGeometry(goalWidth, 0.16, 0.16),
        cyanSide ? this.youEmissive : this.botEmissive
      );
      trim.position.set(0, goalHeight + 0.1, z - end * 0.4);
      this.group.add(trim);

      const banner = new THREE.Mesh(
        new THREE.PlaneGeometry(29, 4.4),
        new THREE.MeshBasicMaterial({
          map: makeBannerTexture(cyanSide ? '#3ee9ff' : '#ff6b3d'),
          transparent: true,
          depthWrite: false,
          toneMapped: false,
        })
      );
      banner.position.set(0, goalHeight + lintelHeight / 2 + 0.2, z - end * 0.37);
      banner.rotation.y = end > 0 ? Math.PI : 0;
      banner.renderOrder = 3;
      this.group.add(banner);
    }
  }

  buildGoals() {
    const { length, goalWidth, goalHeight, goalDepth, width } = ARENA;
    for (const end of [-1, 1]) {
      const teamColor = end > 0 ? YOU : BOT;
      const emissive = end > 0 ? this.youEmissive : this.botEmissive;
      const goalZ = end * (length / 2);
      const backZ = end * (length / 2 + goalDepth);
      const midZ = (goalZ + backZ) / 2;

      const floor = makeBox(goalWidth, 0.08, goalDepth, this.darkMaterial, 0, 0.04, midZ);
      this.group.add(floor);

      const sideMat = this.frameMaterial;
      for (const side of [-1, 1]) {
        const wall = makeBox(0.3, goalHeight, goalDepth, sideMat, side * (goalWidth / 2 + 0.15), goalHeight / 2, midZ);
        this.group.add(wall);

        const sideNet = new THREE.Mesh(
          new THREE.PlaneGeometry(goalDepth - 0.4, goalHeight - 0.5),
          this.netMaterial
        );
        sideNet.rotation.y = side * Math.PI / 2;
        sideNet.position.set(side * (goalWidth / 2 - 0.05), goalHeight / 2, midZ);
        this.group.add(sideNet);
      }

      this.group.add(makeBox(goalWidth + 0.6, goalHeight + 0.2, 0.35, sideMat, 0, goalHeight / 2, backZ));
      this.group.add(makeBox(goalWidth + 0.6, 0.24, goalDepth + 0.4, sideMat, 0, goalHeight + 0.06, midZ));

      const backNet = new THREE.Mesh(
        new THREE.PlaneGeometry(goalWidth - 0.45, goalHeight - 0.45),
        this.netMaterial
      );
      backNet.position.set(0, goalHeight / 2, backZ - end * 0.2);
      backNet.rotation.y = end > 0 ? Math.PI : 0;
      this.group.add(backNet);

      const topNet = new THREE.Mesh(new THREE.PlaneGeometry(goalWidth - 0.45, goalDepth - 0.4), this.netMaterial);
      topNet.rotation.x = Math.PI / 2;
      topNet.position.set(0, goalHeight - 0.08, midZ);
      this.group.add(topNet);

      // Glowing frame posts and crossbar.
      const postGeo = new THREE.CylinderGeometry(0.23, 0.23, goalHeight, 12);
      for (const side of [-1, 1]) {
        const post = new THREE.Mesh(postGeo, emissive);
        post.position.set(side * (goalWidth / 2), goalHeight / 2, goalZ);
        this.group.add(post);
        const backPost = new THREE.Mesh(postGeo, this.frameMaterial);
        backPost.position.set(side * (goalWidth / 2), goalHeight / 2, backZ);
        this.group.add(backPost);
      }
      const crossbar = new THREE.Mesh(new THREE.CylinderGeometry(0.23, 0.23, goalWidth, 12), emissive);
      crossbar.rotation.z = Math.PI / 2;
      crossbar.position.set(0, goalHeight, goalZ);
      this.group.add(crossbar);

      const goalLine = new THREE.Mesh(new THREE.BoxGeometry(goalWidth, 0.06, 0.5), emissive);
      goalLine.position.set(0, 0.06, goalZ);
      this.group.add(goalLine);

      const halo = new THREE.Sprite(new THREE.SpriteMaterial({
        map: this.haloTexture,
        color: teamColor,
        transparent: true,
        opacity: 0.55,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        toneMapped: false,
      }));
      halo.scale.set(goalWidth * 1.55, goalHeight * 1.8, 1);
      halo.position.set(0, goalHeight * 0.48, backZ - end * 0.8);
      this.group.add(halo);
      this.goalHalos.push(halo);

      const light = new THREE.PointLight(teamColor, 110, 32, 2);
      light.position.set(0, goalHeight * 0.55, end * (length / 2 + 3.5));
      this.group.add(light);
      this.lights.push(light);

      // Pit lane strips leading into the goal mouth.
      for (const side of [-1, 1]) {
        const strip = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.05, 6), emissive);
        strip.position.set(side * 11.9, 0.05, end * (length / 2 - 3));
        this.group.add(strip);
      }
    }
  }

  buildStands() {
    const { width, length } = ARENA;
    const standMat = new THREE.MeshStandardMaterial({ color: 0x080f1a, roughness: 0.82, metalness: 0.3 });
    const stepGlow = new THREE.MeshStandardMaterial({
      color: 0x0a121e,
      emissive: 0x3f8fae,
      emissiveIntensity: 0.65,
      roughness: 0.6,
    });

    const spectatorPositions = [];
    const spectatorColors = [];

    for (const side of [-1, 1]) {
      for (let row = 0; row < 4; row += 1) {
        const x = side * (width / 2 + 4.6 + row * 2.7);
        const y = 6.4 + row * 1.7;
        const stand = makeBox(2.8, 1.3, length + 4, standMat, x, y - 0.75, 0, { receive: false });
        this.group.add(stand);
        const lip = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.12, length + 4), stepGlow);
        lip.position.set(x - side * 1.45, y - 0.1, 0);
        this.group.add(lip);

        const count = 92;
        for (let i = 0; i < count; i += 1) {
          if (Math.random() < 0.16) continue;
          spectatorPositions.push(
            x + rand(-0.8, 0.8) + side * 0.2,
            y + 0.5,
            -length / 2 + rand(0, length)
          );
          const roll = Math.random();
          const color = roll < 0.2 ? 0x3ee9ff : roll < 0.38 ? 0xff6b3d : roll < 0.6 ? 0xd8e8f2 : 0x1b2b3d;
          const c = new THREE.Color(color);
          c.multiplyScalar(rand(0.55, 1));
          spectatorColors.push(c.r, c.g, c.b);
        }
      }
    }

    const count = spectatorPositions.length / 3;
    const geometry = new THREE.BoxGeometry(0.42, 0.72, 0.42);
    const crowd = new THREE.InstancedMesh(geometry, this.crowdMaterial, count);
    const matrix = new THREE.Matrix4();
    const color = new THREE.Color();
    for (let i = 0; i < count; i += 1) {
      matrix.makeTranslation(
        spectatorPositions[i * 3],
        spectatorPositions[i * 3 + 1],
        spectatorPositions[i * 3 + 2]
      );
      matrix.multiply(new THREE.Matrix4().makeScale(1, rand(0.85, 1.15), 1));
      crowd.setMatrixAt(i, matrix);
      color.setRGB(spectatorColors[i * 3], spectatorColors[i * 3 + 1], spectatorColors[i * 3 + 2]);
      crowd.setColorAt(i, color);
    }
    crowd.instanceMatrix.needsUpdate = true;
    if (crowd.instanceColor) crowd.instanceColor.needsUpdate = true;
    this.group.add(crowd);

    // Back-of-house glow walls behind the stands.
    const backdrop = new THREE.Mesh(
      new THREE.PlaneGeometry(length + 12, 12),
      new THREE.MeshStandardMaterial({
        color: 0x03070e,
        emissive: 0x0a1626,
        emissiveIntensity: 0.6,
        roughness: 0.9,
      })
    );
    backdrop.rotation.y = Math.PI / 2;
    backdrop.position.set(-(width / 2 + 17), 13, 0);
    this.group.add(backdrop);
    const backdrop2 = backdrop.clone();
    backdrop2.rotation.y = -Math.PI / 2;
    backdrop2.position.x = width / 2 + 17;
    this.group.add(backdrop2);
  }

  buildCeiling() {
    const { width, length, ceiling } = ARENA;
    const ceilingPlane = new THREE.Mesh(
      new THREE.PlaneGeometry(width + 44, length + 34),
      new THREE.MeshStandardMaterial({ color: 0x02050b, roughness: 0.95, metalness: 0.1 })
    );
    ceilingPlane.rotation.x = Math.PI / 2;
    ceilingPlane.position.y = ceiling + 2;
    this.group.add(ceilingPlane);

    const trussMat = this.frameMaterial;
    for (let z = -length / 2; z <= length / 2; z += 15) {
      this.group.add(makeBox(width + 14, 0.5, 0.5, trussMat, 0, ceiling - 0.8, z, { receive: false }));
    }
    for (const x of [-width / 2 - 2, width / 2 + 2]) {
      this.group.add(makeBox(0.5, 0.5, length + 6, trussMat, x, ceiling - 0.8, 0, { receive: false }));
    }
    for (const x of [-12, 12]) {
      for (const z of [-26, 0, 26]) {
        const bank = makeBox(9.5, 0.3, 1.6, this.lightBankMaterial, x, ceiling - 1.4, z, { receive: false });
        this.group.add(bank);
        const glow = new THREE.Sprite(new THREE.SpriteMaterial({
          map: this.glowTexture,
          color: 0xdff8ff,
          transparent: true,
          opacity: 0.5,
          blending: THREE.AdditiveBlending,
          depthWrite: false,
          toneMapped: false,
        }));
        glow.scale.set(13, 4.5, 1);
        glow.position.set(x, ceiling - 1.7, z);
        this.group.add(glow);

        const light = new THREE.PointLight(0xd9f4ff, 75, 44, 2);
        light.position.set(x, ceiling - 2.2, z);
        this.group.add(light);
        this.lights.push(light);
      }
    }
  }

  buildLights() {
    const hemi = new THREE.HemisphereLight(0x78d8ff, 0x080b12, 0.5);
    this.scene.add(hemi);

    const key = new THREE.DirectionalLight(0xe6f8ff, 2.6);
    key.position.set(18, 38, 16);
    key.castShadow = true;
    key.shadow.mapSize.set(2048, 2048);
    key.shadow.camera.left = -58;
    key.shadow.camera.right = 58;
    key.shadow.camera.top = 62;
    key.shadow.camera.bottom = -62;
    key.shadow.camera.near = 1;
    key.shadow.camera.far = 120;
    key.shadow.bias = -0.0004;
    key.shadow.normalBias = 0.03;
    this.scene.add(key);
    this.keyLight = key;

    const fill = new THREE.DirectionalLight(0x2e6dff, 0.65);
    fill.position.set(-26, 20, -24);
    this.scene.add(fill);

    const warm = new THREE.DirectionalLight(0xff8c55, 0.35);
    warm.position.set(20, 12, -30);
    this.scene.add(warm);
  }

  buildPads() {
    const big = [
      [-(ARENA.width / 2 - 7), -(ARENA.length / 4)],
      [ARENA.width / 2 - 7, -(ARENA.length / 4)],
      [-(ARENA.width / 2 - 7), ARENA.length / 4],
      [ARENA.width / 2 - 7, ARENA.length / 4],
    ];
    const small = [
      [-20, -34], [0, -36], [20, -34],
      [-24, -14], [24, -14],
      [-24, 14], [24, 14],
      [-20, 34], [0, 36], [20, 34],
      [0, -14], [0, 14],
    ];

    for (const [x, z] of big) this.addPad(x, z, true);
    for (const [x, z] of small) this.addPad(x, z, false);
  }

  addPad(x, z, big) {
    const amount = big ? 100 : 12;
    const radius = big ? 2.5 : 1.55;
    const group = new THREE.Group();
    group.position.set(x, 0.06, z);

    const color = big ? 0xffcf6b : 0xff9d4d;
    const discMat = new THREE.MeshBasicMaterial({
      color,
      transparent: true,
      opacity: big ? 0.25 : 0.18,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
      side: THREE.DoubleSide,
    });
    const disc = new THREE.Mesh(new THREE.CircleGeometry(radius, 32), discMat);
    disc.rotation.x = -Math.PI / 2;
    group.add(disc);

    const ringMat = new THREE.MeshBasicMaterial({
      color,
      transparent: true,
      opacity: 0.85,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
    });
    const ring = new THREE.Mesh(new THREE.RingGeometry(radius * 0.72, radius * 0.86, 32), ringMat);
    ring.rotation.x = -Math.PI / 2;
    ring.position.y = 0.01;
    group.add(ring);

    const inner = new THREE.Mesh(new THREE.RingGeometry(radius * 0.26, radius * 0.36, 6), ringMat.clone());
    inner.rotation.x = -Math.PI / 2;
    inner.position.y = 0.012;
    group.add(inner);

    const glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: this.glowTexture,
      color,
      transparent: true,
      opacity: big ? 0.65 : 0.4,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
    }));
    glow.scale.setScalar(radius * (big ? 5 : 3.8));
    glow.position.y = 0.2;
    group.add(glow);

    if (big) {
      const beam = new THREE.Mesh(
        new THREE.CylinderGeometry(radius * 0.55, radius * 0.9, 5.5, 16, 1, true),
        new THREE.MeshBasicMaterial({
          color,
          transparent: true,
          opacity: 0.07,
          blending: THREE.AdditiveBlending,
          depthWrite: false,
          side: THREE.DoubleSide,
          toneMapped: false,
        })
      );
      beam.position.y = 2.8;
      group.add(beam);
    }

    this.group.add(group);
    this.pads.push({
      x, z, radius, amount, big, group, ring, inner, disc, glow,
      active: true,
      respawn: big ? 7 : 4,
      timer: 0,
      phase: Math.random() * TAU,
    });
  }

  checkPickups(car, onPickup) {
    if (!car) return;
    for (const pad of this.pads) {
      if (!pad.active) continue;
      const dx = car.pos.x - pad.x;
      const dz = car.pos.z - pad.z;
      if (dx * dx + dz * dz > (pad.radius + 1.2) * (pad.radius + 1.2)) continue;
      if (car.pos.y > 3.2) continue;
      pad.active = false;
      pad.timer = pad.respawn;
      pad.group.visible = false;
      onPickup?.(pad);
    }
  }

  update(dt) {
    this.time += dt;
    const t = this.time;
    for (const pad of this.pads) {
      if (!pad.active) {
        pad.timer -= dt;
        if (pad.timer <= 0) {
          pad.active = true;
          pad.group.visible = true;
          pad.group.scale.setScalar(0.2);
        }
        continue;
      }
      const pulse = 1 + Math.sin(t * 2.6 + pad.phase) * 0.05;
      pad.group.scale.setScalar(pulse);
      pad.ring.rotation.z += dt * (pad.big ? 0.9 : -1.3);
      pad.inner.rotation.z -= dt * 1.6;
      pad.disc.material.opacity = (pad.big ? 0.25 : 0.18) + Math.sin(t * 3 + pad.phase) * 0.05;
    }
    for (const [index, halo] of this.goalHalos.entries()) {
      halo.material.opacity = 0.42 + Math.sin(t * 1.7 + index * 1.6) * 0.12;
    }
    if (this.keyLight) {
      this.keyLight.position.z = 16 + Math.sin(t * 0.13) * 1.5;
    }
  }
}

