import * as THREE from 'three';
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';
import { clamp, damp, rand, TAU } from './utils.js';

export const CAR_PHYSICS = {
  rideHeight: 0.86,
  gravity: 33,
  jumpVelocity: 13.4,
  doubleJumpVelocity: 8.2,
  maxGroundSpeed: 31,
  maxBoostSpeed: 47,
  accel: 34,
  reverseAccel: 23,
  boostAccel: 53,
  boostDrain: 31,
  steerRate: 2.55,
};

export class Car {
  constructor(scene, { color = 0x18b6d8, accent = 0x3ee9ff, isPlayer = true, name = 'YOU' } = {}) {
    this.scene = scene;
    this.isPlayer = isPlayer;
    this.name = name;
    this.color = color;
    this.accentColor = accent;

    this.pos = new THREE.Vector3();
    this.vel = new THREE.Vector3();
    this.yaw = 0;
    this.grounded = true;
    this.boosting = false;
    this.boost = 100;
    this.jumps = 0;
    this.airTime = 0;
    this.jumpHeld = false;
    this.wheelSpin = 0;
    this.flipTimer = 0;
    this.flipDirection = 1;
    this.hitFlash = 0;
    this.stats = { topSpeed: 0, hits: 0, boostUsed: 0 };

    this.group = new THREE.Group();
    this.group.name = `car-${name}`;
    this.tilt = new THREE.Group();
    this.group.add(this.tilt);
    scene.add(this.group);

    this.wheels = [];
    this.flames = [];
    this.build();
    this.reset(0, 0, 0);
  }

  build() {
    const paint = new THREE.MeshPhysicalMaterial({
      color: this.color,
      metalness: 0.5,
      roughness: 0.24,
      clearcoat: 1,
      clearcoatRoughness: 0.08,
      envMapIntensity: 1.15,
    });
    const accent = new THREE.MeshStandardMaterial({
      color: 0x051018,
      emissive: this.accentColor,
      emissiveIntensity: 3.6,
      roughness: 0.32,
      metalness: 0.5,
    });
    const dark = new THREE.MeshStandardMaterial({
      color: 0x0a1018,
      metalness: 0.7,
      roughness: 0.38,
      envMapIntensity: 0.8,
    });
    const rubber = new THREE.MeshStandardMaterial({ color: 0x080a0e, roughness: 0.95, metalness: 0.05 });
    const rim = new THREE.MeshStandardMaterial({
      color: 0x2a3848,
      metalness: 0.95,
      roughness: 0.18,
      envMapIntensity: 1.3,
    });
    const glass = new THREE.MeshPhysicalMaterial({
      color: 0x07131f,
      metalness: 0.85,
      roughness: 0.06,
      transparent: true,
      opacity: 0.92,
      envMapIntensity: 1.6,
    });

    const add = (mesh, parent = this.tilt) => {
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    };

    const skirt = add(new THREE.Mesh(new RoundedBoxGeometry(1.92, 0.32, 3.9, 3, 0.12), dark));
    skirt.position.set(0, -0.02, 0);

    const body = add(new THREE.Mesh(new RoundedBoxGeometry(2.06, 0.5, 4.02, 4, 0.22), paint));
    body.position.set(0, 0.21, 0);

    const nose = add(new THREE.Mesh(new RoundedBoxGeometry(1.66, 0.26, 0.95, 3, 0.12), paint));
    nose.position.set(0, 0.17, -1.86);

    const cabin = add(new THREE.Mesh(new RoundedBoxGeometry(1.46, 0.52, 1.82, 3, 0.18), glass));
    cabin.position.set(0, 0.6, 0.24);

    const roof = add(new THREE.Mesh(new RoundedBoxGeometry(1.2, 0.075, 1.18, 2, 0.03), paint));
    roof.position.set(0, 0.865, 0.24);

    const roofStripe = add(new THREE.Mesh(new THREE.BoxGeometry(0.28, 0.02, 1.1), accent));
    roofStripe.position.set(0, 0.91, 0.24);

    const hoodStripe = add(new THREE.Mesh(new THREE.BoxGeometry(0.28, 0.02, 1.4), accent));
    hoodStripe.position.set(0, 0.42, -1.2);

    const splitter = add(new THREE.Mesh(new THREE.BoxGeometry(2.06, 0.07, 0.45), dark));
    splitter.position.set(0, -0.13, -1.94);

    const rearBumper = add(new THREE.Mesh(new THREE.BoxGeometry(1.98, 0.16, 0.4), dark));
    rearBumper.position.set(0, 0.02, 1.94);

    // headlight bars
    for (const side of [-1, 1]) {
      const lamp = add(new THREE.Mesh(new THREE.BoxGeometry(0.44, 0.075, 0.06), new THREE.MeshStandardMaterial({
        color: 0xffffff,
        emissive: 0xdff8ff,
        emissiveIntensity: 5,
        toneMapped: false,
      })));
      lamp.position.set(side * 0.62, 0.27, -2.01);

      const tail = add(new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.075, 0.05), new THREE.MeshStandardMaterial({
        color: 0xff2a1a,
        emissive: 0xff2a1a,
        emissiveIntensity: 4,
        toneMapped: false,
      })));
      tail.position.set(side * 0.6, 0.27, 2.02);
    }

    // spoiler
    const wing = add(new THREE.Mesh(new THREE.BoxGeometry(1.98, 0.07, 0.42), paint));
    wing.position.set(0, 0.82, 1.82);
    for (const side of [-1, 1]) {
      const plate = add(new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.26, 0.46), dark));
      plate.position.set(side * 0.96, 0.72, 1.82);
      const strut = add(new THREE.Mesh(new THREE.BoxGeometry(0.09, 0.3, 0.09), dark));
      strut.position.set(side * 0.58, 0.66, 1.8);
    }

    // wheels
    const tireGeo = new THREE.CylinderGeometry(0.45, 0.45, 0.34, 20, 1);
    tireGeo.rotateZ(Math.PI / 2);
    const rimGeo = new THREE.CylinderGeometry(0.24, 0.24, 0.36, 12, 1);
    rimGeo.rotateZ(Math.PI / 2);
    const wheelPositions = [
      [-1.02, -0.4, -1.3, true],
      [1.02, -0.4, -1.3, true],
      [-1.02, -0.4, 1.3, false],
      [1.02, -0.4, 1.3, false],
    ];
    for (const [x, y, z, steer] of wheelPositions) {
      const pivot = new THREE.Group();
      pivot.position.set(x, y, z);
      this.tilt.add(pivot);
      const wheel = new THREE.Mesh(tireGeo, rubber);
      wheel.castShadow = true;
      wheel.receiveShadow = true;
      pivot.add(wheel);
      const hub = new THREE.Mesh(rimGeo, rim);
      wheel.add(hub);
      const glowHub = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.1, 0.375, 8), accent);
      glowHub.rotation.z = Math.PI / 2;
      wheel.add(glowHub);
      this.wheels.push({ pivot, wheel, steer, x, z });
    }

    // exhaust nozzles and flames
    for (const side of [-1, 1]) {
      const nozzle = new THREE.Mesh(new THREE.CylinderGeometry(0.17, 0.2, 0.28, 12), dark);
      nozzle.rotation.x = Math.PI / 2;
      nozzle.position.set(side * 0.44, 0.1, 2.02);
      this.tilt.add(nozzle);

      const flameMat = new THREE.MeshBasicMaterial({
        color: this.accentColor,
        transparent: true,
        opacity: 0,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        side: THREE.DoubleSide,
        toneMapped: false,
      });
      const flame = new THREE.Mesh(new THREE.ConeGeometry(0.25, 1.45, 12, 1, true), flameMat);
      flame.rotation.x = Math.PI / 2;
      flame.position.set(side * 0.44, 0.1, 2.75);
      this.tilt.add(flame);
      this.flames.push(flame);

      const coreMat = flameMat.clone();
      coreMat.color.setHex(0xffffff);
      const core = new THREE.Mesh(new THREE.ConeGeometry(0.11, 0.85, 10, 1, true), coreMat);
      core.rotation.x = Math.PI / 2;
      core.position.set(side * 0.44, 0.1, 2.48);
      this.tilt.add(core);
      this.flames.push(core);
    }

    // underglow
    const under = new THREE.Mesh(
      new THREE.CircleGeometry(1.75, 28),
      new THREE.MeshBasicMaterial({
        color: this.accentColor,
        transparent: true,
        opacity: 0.34,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        toneMapped: false,
      })
    );
    under.rotation.x = -Math.PI / 2;
    under.position.y = -0.82;
    under.scale.set(1, 1.7, 1);
    this.group.add(under);
    this.underglow = under;

    const glowSprite = new THREE.Sprite(new THREE.SpriteMaterial({
      color: this.accentColor,
      transparent: true,
      opacity: 0.5,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
      map: null,
    }));
    glowSprite.scale.set(3.4, 1.6, 1);
    glowSprite.position.set(0, 0.05, 2.3);
    this.tilt.add(glowSprite);
    this.exhaustGlow = glowSprite;

    this.body = body;
    this.paintMaterial = paint;
    this.accentMaterial = accent;
  }

  reset(x, z, yaw) {
    this.pos.set(x, CAR_PHYSICS.rideHeight, z);
    this.vel.set(0, 0, 0);
    this.yaw = yaw;
    this.grounded = true;
    this.boosting = false;
    this.boost = 100;
    this.jumps = 0;
    this.airTime = 0;
    this.jumpHeld = false;
    this.flipTimer = 0;
    this.wheelSpin = 0;
    this.group.position.copy(this.pos);
    this.group.rotation.y = yaw;
    this.tilt.rotation.set(0, 0, 0);
    this.syncVisual(0);
  }

  forward(out = new THREE.Vector3()) {
    return out.set(-Math.sin(this.yaw), 0, -Math.cos(this.yaw));
  }

  right(out = new THREE.Vector3()) {
    return out.set(Math.cos(this.yaw), 0, -Math.sin(this.yaw));
  }

  speed() {
    return Math.hypot(this.vel.x, this.vel.z);
  }

  update(dt, controls, { audio, particles, onJump, onDoubleJump, onWallHit } = {}) {
    const forward = this.forward();
    const right = this.right();
    const throttle = controls.throttle;
    const steer = controls.steer;
    const jumpPressed = controls.jump && !this.jumpHeld;
    this.jumpHeld = controls.jump;
    if (jumpPressed) this.jumps = this.jumps || 0;

    let speedF = this.vel.dot(forward);
    let speedR = this.vel.dot(right);
    const wasGrounded = this.grounded;
    this.boosting = false;

    if (this.grounded) {
      const steerScale = clamp(Math.abs(speedF) / 5, 0, 1);
      const direction = speedF < -0.5 ? -1 : 1;
      const rate = controls.handbrake ? 3.3 : CAR_PHYSICS.steerRate;
      this.yaw += steer * rate * steerScale * direction * dt;

      if (throttle > 0) {
        const fade = 1 - clamp(speedF / CAR_PHYSICS.maxGroundSpeed, 0, 1) * 0.82;
        this.vel.addScaledVector(forward, CAR_PHYSICS.accel * throttle * fade * dt);
      } else if (throttle < 0) {
        const fade = 1 - clamp(-speedF / 15, 0, 1) * 0.55;
        this.vel.addScaledVector(forward, CAR_PHYSICS.reverseAccel * throttle * fade * dt);
      }

      if (controls.boost && this.boost > 0.4) {
        const fade = 1 - clamp(speedF / CAR_PHYSICS.maxBoostSpeed, 0, 1) * 0.62;
        this.vel.addScaledVector(forward, CAR_PHYSICS.boostAccel * fade * dt);
        this.boost = Math.max(0, this.boost - CAR_PHYSICS.boostDrain * dt);
        this.stats.boostUsed += CAR_PHYSICS.boostDrain * dt;
        this.boosting = true;
      }

      speedR = this.vel.dot(right);
      const grip = controls.handbrake ? 2.1 : 9.5;
      this.vel.addScaledVector(right, -speedR * Math.min(1, grip * dt));

      speedF = this.vel.dot(forward);
      const cap = this.boosting ? CAR_PHYSICS.maxBoostSpeed : CAR_PHYSICS.maxGroundSpeed;
      if (speedF > cap) this.vel.addScaledVector(forward, (cap - speedF) * Math.min(1, 12 * dt));

      speedF = this.vel.dot(forward);
      const rolling = throttle === 0 ? 1.2 : 0.18;
      this.vel.addScaledVector(forward, -speedF * rolling * dt);

      if (jumpPressed) {
        this.vel.y = CAR_PHYSICS.jumpVelocity;
        this.grounded = false;
        this.jumps = 1;
        this.airTime = 0;
        this.pos.y += 0.02;
        audio?.playJump();
        onJump?.();
        if (particles) {
          const point = this.pos.clone().addScaledVector(forward, -1.2);
          point.y = 0.2;
          particles.burst(point, 8, {
            color: new THREE.Color(this.accentColor),
            speed: 3.2,
            size: 0.6,
            life: 0.35,
            gravity: 2,
            drag: 2.2,
            spread: 1.4,
          });
        }
      }
    } else {
      this.airTime += dt;
      this.vel.y -= CAR_PHYSICS.gravity * dt;
      this.yaw += steer * 1.85 * dt;

      if (controls.boost && this.boost > 0.4) {
        this.vel.addScaledVector(forward, 27 * dt);
        this.vel.y += 9.5 * dt;
        this.boost = Math.max(0, this.boost - CAR_PHYSICS.boostDrain * dt);
        this.stats.boostUsed += CAR_PHYSICS.boostDrain * dt;
        this.boosting = true;
      }

      if (jumpPressed && this.jumps === 1 && this.airTime > 0.1) {
        this.jumps = 2;
        this.vel.y = Math.max(this.vel.y, CAR_PHYSICS.doubleJumpVelocity);
        this.vel.addScaledVector(forward, 4.2);
        this.flipTimer = 0.5;
        this.flipDirection = Math.sign(steer) || 1;
        audio?.playDoubleJump();
        onDoubleJump?.();
        if (particles) {
          const point = this.pos.clone();
          particles.burst(point, 12, {
            color: new THREE.Color(0xffffff),
            speed: 5,
            size: 0.5,
            life: 0.3,
            gravity: 0,
            drag: 3,
          });
        }
      }
    }

    // clamp horizontal speed globally
    const horiz = Math.hypot(this.vel.x, this.vel.z);
    const hardCap = CAR_PHYSICS.maxBoostSpeed + 2;
    if (horiz > hardCap) {
      this.vel.x *= hardCap / horiz;
      this.vel.z *= hardCap / horiz;
    }

    this.pos.addScaledVector(this.vel, dt);

    // ground contact
    if (this.pos.y <= CAR_PHYSICS.rideHeight) {
      this.pos.y = CAR_PHYSICS.rideHeight;
      if (this.vel.y < 0) this.vel.y = 0;
      if (!wasGrounded && this.airTime > 0.08) {
        audio?.playWall(1.4);
        if (particles) {
          particles.burst(this.pos.clone().setY(0.14), 10, {
            color: new THREE.Color(0xcfeeff),
            speed: 2.5,
            size: 0.45,
            life: 0.35,
            gravity: 4,
            drag: 2.5,
            spread: 1.8,
          });
        }
      }
      this.grounded = true;
      this.jumps = 0;
      this.airTime = 0;
    } else {
      this.grounded = false;
    }

    // arena bounds
    const xLimit = 64 / 2 - 1.55;
    const zLimit = 92 / 2 - 2.4;
    if (Math.abs(this.pos.x) > xLimit) {
      const sign = Math.sign(this.pos.x);
      this.pos.x = sign * xLimit;
      if (Math.sign(this.vel.x) === sign) {
        const impact = Math.abs(this.vel.x);
        this.vel.x *= -0.32;
        if (impact > 5) {
          audio?.playWall(impact);
          onWallHit?.(impact);
          this.shake = Math.min(0.3, impact * 0.012);
        }
      }
    }
    if (Math.abs(this.pos.z) > zLimit) {
      const sign = Math.sign(this.pos.z);
      this.pos.z = sign * zLimit;
      if (Math.sign(this.vel.z) === sign) {
        const impact = Math.abs(this.vel.z);
        this.vel.z *= -0.32;
        if (impact > 5) {
          audio?.playWall(impact);
          onWallHit?.(impact);
          this.shake = Math.min(0.3, impact * 0.012);
        }
      }
    }

    if (this.flipTimer > 0) this.flipTimer = Math.max(0, this.flipTimer - dt);
    if (this.boosting && particles) this.emitBoost(particles, forward, right);
    if (this.boosting && audio && Math.random() < dt * 8) audio.playBoostStart();

    this.stats.topSpeed = Math.max(this.stats.topSpeed, this.speed() * 3.6);
    this.syncVisual(dt, controls);
  }

  emitBoost(particles, forward, right) {
    const base = this.pos.clone().addScaledVector(forward, -2.1);
    base.y += 0.12;
    for (const side of [-1, 1]) {
      const point = base.clone().addScaledVector(right, side * 0.44);
      particles.spawn({
        position: point,
        velocity: forward.clone().multiplyScalar(-rand(7, 15)).add(new THREE.Vector3(rand(-1.6, 1.6), rand(-0.4, 1.5), rand(-1.6, 1.6))),
        color: new THREE.Color(Math.random() < 0.35 ? 0xffffff : this.accentColor),
        size: rand(0.5, 1.15),
        life: rand(0.18, 0.4),
        gravity: -2.5,
        drag: 1.8,
        grow: 1.4,
        fade: 0.9,
      });
    }
  }

  syncVisual(dt, controls = { throttle: 0, steer: 0 }) {
    this.group.position.copy(this.pos);
    this.group.rotation.y = this.yaw;

    const speed = this.speed();
    const targetRoll = -controls.steer * clamp(speed / 36, 0, 1) * 0.17;
    const accelerationPitch = this.grounded ? -clamp((this.boosting ? 0.1 : 0) + (controls.throttle || 0) * 0.03, -0.1, 0.1) : 0;
    let airPitch = 0;
    if (!this.grounded) airPitch = clamp(this.vel.y * 0.012, -0.2, 0.2);

    let flip = 0;
    if (this.flipTimer > 0) {
      const progress = 1 - this.flipTimer / 0.5;
      flip = -TAU * progress * this.flipDirection;
    }

    this.tilt.rotation.z = damp(this.tilt.rotation.z, targetRoll, 8, dt || 0.016);
    this.tilt.rotation.x = damp(this.tilt.rotation.x, accelerationPitch + airPitch, 6, dt || 0.016) + flip;

    this.wheelSpin += (speed * (this.vel.dot(this.forward()) >= 0 ? 1 : -1) * (dt || 0.016)) / 0.45;
    const steerAngle = -controls.steer * 0.42;
    for (const wheel of this.wheels) {
      wheel.wheel.rotation.x = this.wheelSpin;
      if (wheel.steer) wheel.pivot.rotation.y = steerAngle;
    }

    const flicker = 0.8 + Math.random() * 0.4;
    for (let i = 0; i < this.flames.length; i += 1) {
      const flame = this.flames[i];
      const isCore = i % 2 === 1;
      flame.visible = true;
      flame.material.opacity = this.boosting ? (isCore ? 0.9 : 0.55) * flicker : 0;
      const length = this.boosting ? (isCore ? 0.75 : 1.15) + Math.random() * 0.45 : 0.2;
      flame.scale.set(1, length, 1);
    }
    if (this.exhaustGlow) {
      this.exhaustGlow.material.opacity = this.boosting ? 0.55 + Math.random() * 0.2 : 0.08;
      this.exhaustGlow.scale.set(this.boosting ? 4.2 : 2.8, this.boosting ? 2.4 : 1.4, 1);
    }
    if (this.underglow) {
      this.underglow.material.opacity = (this.grounded ? 0.3 : 0.1) + (this.boosting ? 0.12 : 0);
    }
  }

  dispose() {
    this.scene.remove(this.group);
  }
}

import * as THREE from 'three';
import { ARENA } from './arena.js';
import { makeBallTexture, makeHaloTexture } from './textures.js';
import { clamp, rand } from './utils.js';

export const BALL_RADIUS = 1.82;

export class Ball {
  constructor(scene) {
    this.scene = scene;
    this.pos = new THREE.Vector3(0, BALL_RADIUS, 0);
    this.vel = new THREE.Vector3();
    this.radius = BALL_RADIUS;
    this.trailClock = 0;
    this.spinAxis = new THREE.Vector3(1, 0, 0);
    this.spinSpeed = 0;

    const material = new THREE.MeshPhysicalMaterial({
      map: makeBallTexture(),
      metalness: 0.32,
      roughness: 0.24,
      clearcoat: 0.85,
      clearcoatRoughness: 0.18,
      envMapIntensity: 1.15,
    });

    this.mesh = new THREE.Mesh(new THREE.SphereGeometry(BALL_RADIUS, 40, 28), material);
    this.mesh.castShadow = true;
    this.mesh.receiveShadow = true;
    this.scene.add(this.mesh);

    this.halo = new THREE.Sprite(new THREE.SpriteMaterial({
      map: makeHaloTexture(),
      color: 0xbdf6ff,
      transparent: true,
      opacity: 0.65,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
    }));
    this.halo.scale.setScalar(BALL_RADIUS * 6.4);
    this.scene.add(this.halo);

    this.light = new THREE.PointLight(0x9deeff, 26, 18, 2);
    this.scene.add(this.light);

    this.reset();
  }

  reset(x = 0, z = 0) {
    this.pos.set(x, BALL_RADIUS + 3, z);
    this.vel.set(rand(-0.5, 0.5), 0.5, rand(-0.5, 0.5));
    this.mesh.position.copy(this.pos);
    this.halo.position.copy(this.pos);
    this.light.position.copy(this.pos);
  }

  update(dt, particles) {
    this.vel.y -= 24 * dt;
    const drag = Math.max(0, 1 - 0.075 * dt);
    this.vel.multiplyScalar(drag);

    this.pos.addScaledVector(this.vel, dt);
    const r = BALL_RADIUS;

    // Floor
    if (this.pos.y < r) {
      this.pos.y = r;
      if (this.vel.y < 0) {
        const bounce = -this.vel.y * 0.72;
        this.vel.y = bounce > 1.2 ? bounce : 0;
        this.vel.x *= 0.992;
        this.vel.z *= 0.992;
        if (bounce > 5 && particles) {
          particles.burst(this.pos.clone().setY(0.15), 12, {
            color: new THREE.Color(0xcfeeff),
            speed: bounce * 0.35,
            size: 0.55,
            life: 0.45,
            gravity: 7,
            drag: 1.8,
            spread: 1.7,
          });
        }
      }
    }

    // Ceiling
    if (this.pos.y > ARENA.wallHeight - r) {
      this.pos.y = ARENA.wallHeight - r;
      if (this.vel.y > 0) this.vel.y *= -0.55;
    }

    // Side walls
    const xLimit = ARENA.width / 2 - r;
    if (Math.abs(this.pos.x) > xLimit) {
      const sign = Math.sign(this.pos.x);
      this.pos.x = sign * xLimit;
      this.vel.x *= -0.78;
    }

    // End walls / goals
    const throughGoal = Math.abs(this.pos.x) < ARENA.goalWidth / 2 - 0.3 && this.pos.y < ARENA.goalHeight - 0.2;
    const zWall = ARENA.length / 2 - r;
    if (!throughGoal) {
      if (Math.abs(this.pos.z) > zWall) {
        const sign = Math.sign(this.pos.z);
        this.pos.z = sign * zWall;
        this.vel.z *= -0.78;
      }
    } else if (Math.abs(this.pos.z) > ARENA.length / 2) {
      const sign = Math.sign(this.pos.z);
      // Constrain the ball inside the goal box once it has crossed the line.
      const goalX = ARENA.goalWidth / 2 - r;
      if (Math.abs(this.pos.x) > goalX) {
        this.pos.x = Math.sign(this.pos.x) * goalX;
        this.vel.x *= -0.4;
      }
      if (this.pos.y > ARENA.goalHeight - r) {
        this.pos.y = ARENA.goalHeight - r;
        if (this.vel.y > 0) this.vel.y *= -0.4;
      }
      const backZ = ARENA.length / 2 + ARENA.goalDepth - r - 0.2;
      if (Math.abs(this.pos.z) > backZ) {
        this.pos.z = sign * backZ;
        this.vel.z *= -0.28;
        this.vel.x *= 0.8;
      }
    }

    // Posts (simple vertical cylinders at the mouth)
    for (const end of [-1, 1]) {
      for (const side of [-1, 1]) {
        const px = side * ARENA.goalWidth / 2;
        const pz = end * ARENA.length / 2;
        const dx = this.pos.x - px;
        const dz = this.pos.z - pz;
        const dist = Math.hypot(dx, dz);
        const min = r + 0.25;
        if (dist < min && this.pos.y < ARENA.goalHeight + r) {
          const nx = dist > 0.001 ? dx / dist : 1;
          const nz = dist > 0.001 ? dz / dist : 0;
          this.pos.x = px + nx * min;
          this.pos.z = pz + nz * min;
          const vn = this.vel.x * nx + this.vel.z * nz;
          if (vn < 0) {
            this.vel.x -= 1.7 * vn * nx;
            this.vel.z -= 1.7 * vn * nz;
            this.vel.multiplyScalar(0.85);
          }
        }
      }
    }

    // Hard speed cap
    const speed = this.vel.length();
    if (speed > 62) this.vel.multiplyScalar(62 / speed);

    // Visuals
    this.mesh.position.copy(this.pos);
    this.halo.position.copy(this.pos);
    this.light.position.copy(this.pos);
    const hSpeed = Math.hypot(this.vel.x, this.vel.z);
    if (hSpeed > 0.1) {
      this.spinAxis.set(this.vel.z, 0, -this.vel.x).normalize();
      this.spinSpeed = hSpeed / BALL_RADIUS;
      this.mesh.rotateOnWorldAxis(this.spinAxis, this.spinSpeed * dt * 0.55);
    }
    this.halo.material.opacity = 0.5 + Math.sin(performance.now() * 0.003) * 0.08 + clamp(speed / 80, 0, 0.25);

    if (particles) {
      this.trailClock += dt;
      const interval = speed > 26 ? 0.012 : 0.026;
      while (this.trailClock > interval) {
        this.trailClock -= interval;
        const tint = new THREE.Color(Math.random() < 0.25 ? 0x6fe8ff : 0xe8fdff);
        particles.spawn({
          position: this.pos.clone().add(new THREE.Vector3(rand(-1, 1), rand(-1, 1), rand(-1, 1)).multiplyScalar(0.9)),
          velocity: new THREE.Vector3(rand(-0.7, 0.7), rand(-0.2, 1.1), rand(-0.7, 0.7)),
          color: tint,
          size: rand(0.45, 1.05),
          life: rand(0.35, 0.7),
          gravity: 1.2,
          drag: 1.4,
          grow: 1.2,
          fade: 1.5,
        });
      }
    }
  }

  collideCar(car) {
    if (Math.abs(this.pos.y - car.pos.y) > 2.5) return 0;

    const dx = this.pos.x - car.pos.x;
    const dz = this.pos.z - car.pos.z;
    const cos = Math.cos(car.yaw);
    const sin = Math.sin(car.yaw);
    const localX = dx * cos - dz * sin;
    const localZ = dx * sin + dz * cos;
    const halfW = 1.05;
    const halfL = 2.08;
    const cx = clamp(localX, -halfW, halfW);
    const cz = clamp(localZ, -halfL, halfL);
    const cy = clamp(this.pos.y - car.pos.y, -0.58, 0.72);

    const worldX = car.pos.x + cx * cos + cz * sin;
    const worldZ = car.pos.z - cx * sin + cz * cos;
    const worldY = car.pos.y + cy;

    let nx = this.pos.x - worldX;
    let ny = this.pos.y - worldY;
    let nz = this.pos.z - worldZ;
    let dist = Math.hypot(nx, ny, nz);

    if (dist > BALL_RADIUS) return 0;
    if (dist < 0.0001) {
      nx = 0; ny = 1; nz = 0; dist = 0.0001;
    }
    nx /= dist; ny /= dist; nz /= dist;

    const penetration = BALL_RADIUS - dist;
    this.pos.x += nx * penetration;
    this.pos.y += ny * penetration;
    this.pos.z += nz * penetration;

    const relX = this.vel.x - car.vel.x;
    const relY = this.vel.y - car.vel.y;
    const relZ = this.vel.z - car.vel.z;
    const vn = relX * nx + relY * ny + relZ * nz;
    if (vn >= 0) return 0;

    const impact = -vn;
    const power = 1.42;
    this.vel.x += nx * impact * power + car.vel.x * 0.22;
    this.vel.y += ny * impact * power + car.vel.y * 0.1;
    this.vel.z += nz * impact * power + car.vel.z * 0.22;

    // A little lift when catching the ball with the nose or roof.
    const carSpeed = car.speed();
    this.vel.y += clamp(carSpeed * 0.1 + impact * 0.06, 0, 5.5);

    // Keep the ball from being pinched through the car.
    if (Math.hypot(this.pos.x - car.pos.x, this.pos.z - car.pos.z) < 2.4) {
      const awayX = this.pos.x - car.pos.x;
      const awayZ = this.pos.z - car.pos.z;
      const len = Math.hypot(awayX, awayZ) || 1;
      this.vel.x += (awayX / len) * impact * 0.25;
      this.vel.z += (awayZ / len) * impact * 0.25;
    }

    car.vel.multiplyScalar(clamp(1 - impact * 0.006, 0.88, 1));
    car.stats.hits += 1;
    this.spinSpeed += impact;

    const speed = this.vel.length();
    if (speed > 62) this.vel.multiplyScalar(62 / speed);
    return impact;
  }
}

import * as THREE from 'three';
import { ARENA } from './arena.js';
import { clamp, rand, wrapAngle } from './utils.js';

const DIFFICULTIES = {
  rookie: {
    label: 'Rookie',
    reaction: 0.3,
    aimError: 2.3,
    lead: 0.35,
    jumpChance: 0.18,
    boostEagerness: 0.45,
    speed: 0.82,
    hesitation: 0.18,
    defense: 0.65,
  },
  pro: {
    label: 'Pro',
    reaction: 0.17,
    aimError: 1.15,
    lead: 0.7,
    jumpChance: 0.48,
    boostEagerness: 0.8,
    speed: 0.94,
    hesitation: 0.05,
    defense: 0.9,
  },
  allstar: {
    label: 'All-Star',
    reaction: 0.1,
    aimError: 0.55,
    lead: 0.95,
    jumpChance: 0.82,
    boostEagerness: 1,
    speed: 1,
    hesitation: 0,
    defense: 1,
  },
};

export class BotController {
  constructor(difficulty = 'pro') {
    this.target = new THREE.Vector3(0, 0, -28);
    this.thinkTimer = 0;
    this.jumpCooldown = 0;
    this.jumpPulse = 0;
    this.stuckTimer = 0;
    this.reverseTimer = 0;
    this.hesitateTimer = 0;
    this.lastPos = new THREE.Vector3();
    this.speed = 1;
    this.config = DIFFICULTIES.pro;
    this.setDifficulty(difficulty);
  }

  setDifficulty(name) {
    this.difficulty = DIFFICULTIES[name] ? name : 'pro';
    this.config = DIFFICULTIES[this.difficulty];
    this.reset();
  }

  reset() {
    this.thinkTimer = 0;
    this.jumpCooldown = 0.5;
    this.jumpPulse = 0;
    this.stuckTimer = 0;
    this.reverseTimer = 0;
    this.hesitateTimer = 0;
  }

  update(dt, bot, ball, { kickoff = false } = {}) {
    const config = this.config;
    const c = config;
    this.jumpCooldown = Math.max(0, this.jumpCooldown - dt);
    this.jumpPulse = Math.max(0, this.jumpPulse - dt);
    this.reverseTimer = Math.max(0, this.reverseTimer - dt);
    this.hesitateTimer = Math.max(0, this.hesitateTimer - dt);
    this.thinkTimer -= dt;

    const ballPos = ball.pos;
    const botPos = bot.pos;

    if (this.thinkTimer <= 0) {
      this.thinkTimer = c.reaction * rand(0.7, 1.35);
      if (Math.random() < c.hesitation) this.hesitateTimer = rand(0.12, 0.32);

      const distance = botPos.distanceTo(ballPos);
      const leadTime = clamp(distance / 40, 0.04, 0.55) * c.lead;
      const predicted = ballPos.clone().addScaledVector(ball.vel, leadTime);
      predicted.y = ballPos.y;

      const goal = new THREE.Vector3(0, 0, ARENA.length / 2 + 2);
      const toGoal = goal.clone().sub(predicted);
      toGoal.y = 0;
      toGoal.normalize();

      // Stand on the opposite side of the ball to push it toward the player's goal.
      const target = predicted.clone().addScaledVector(toGoal, -(ball.radius + 2.7));

      // If the ball is deep in NOVA's half, bias harder toward a clearing angle.
      if (predicted.z < -ARENA.length * 0.22) {
        const clearance = new THREE.Vector3(Math.sign(predicted.x) * 6 || 0, 0, 18);
        target.addScaledVector(clearance, 0.25 * c.defense);
      }

      const side = new THREE.Vector3(-toGoal.z, 0, toGoal.x);
      const noise = rand(-c.aimError, c.aimError);
      target.addScaledVector(side, noise);
      target.x = clamp(target.x, -ARENA.width / 2 + 3.2, ARENA.width / 2 - 3.2);
      target.z = clamp(target.z, -ARENA.length / 2 + 3.2, ARENA.length / 2 - 3.2);
      if (!kickoff) {
        this.target.copy(target);
      } else {
        this.target.set(ballPos.x, 0, ballPos.z);
      }
    }

    const toTarget = this.target.clone().sub(botPos);
    toTarget.y = 0;
    const dist = toTarget.length();
    const desiredYaw = Math.atan2(-toTarget.x, -toTarget.z);
    let delta = wrapAngle(desiredYaw - bot.yaw);

    let steer = clamp(delta * 2.3, -1, 1);
    let throttle = 1;
    if (Math.abs(delta) > 0.62) throttle = 0.38;
    if (Math.abs(delta) > 1.55) throttle = -0.65;
    if (this.hesitateTimer > 0) throttle = 0;

    // Reverse out of a wall / pile-up.
    const moved = botPos.distanceTo(this.lastPos);
    this.lastPos.copy(botPos);
    if (moved < 0.05 && !bot.grounded) {
      // airborne, ignore
    } else if (moved < 0.035 && throttle > 0.5) {
      this.stuckTimer += dt;
      if (this.stuckTimer > 0.65) {
        this.stuckTimer = 0;
        this.reverseTimer = 0.65;
      }
    } else {
      this.stuckTimer = Math.max(0, this.stuckTimer - dt * 2);
    }
    if (this.reverseTimer > 0) {
      throttle = -0.9;
      steer = -steer;
    }

    // Use the handbrake on sharp, fast turns.
    const handbrake = Math.abs(delta) > 1.25 && bot.speed() > 15;

    // Boost when lined up and far from the ball, or when chasing on a kickoff.
    let boost = false;
    if (bot.boost > 6 && Math.abs(delta) < 0.4) {
      if (kickoff) boost = true;
      else if (dist > 9 && bot.boost > 12) boost = Math.random() < c.boostEagerness;
    }
    if (this.reverseTimer > 0) boost = false;

    // Air game: challenge lobbed balls, then boost through the aerial.
    let jump = false;
    const horizontal = Math.hypot(ballPos.x - botPos.x, ballPos.z - botPos.z);
    const height = ballPos.y - botPos.y;

    if (bot.grounded && this.jumpCooldown <= 0 && horizontal < 8 && height > 2.4 && height < 8.5) {
      if (Math.random() < c.jumpChance * 0.24) {
        this.jumpPulse = 0.08;
        this.jumpCooldown = rand(1.1, 2.2);
      }
    }
    if (!bot.grounded && bot.jumps === 1 && bot.airTime > 0.18 && height > 1.6 && horizontal < 6 && this.jumpCooldown <= 0.55) {
      if (Math.random() < c.jumpChance * 0.12) {
        this.jumpPulse = 0.08;
        this.jumpCooldown = 1.4;
      }
    }
    if (!bot.grounded) {
      if (ballPos.y > botPos.y) {
        const ballYaw = Math.atan2(-(ballPos.x - botPos.x), -(ballPos.z - botPos.z));
        const airDelta = wrapAngle(ballYaw - bot.yaw);
        steer = clamp(airDelta * 2.4, -1, 1);
        boost = bot.boost > 4 && Math.abs(airDelta) < 1.1 && height > 0.8;
      }
      throttle = 0;
    }

    jump = this.jumpPulse > 0;

    if (throttle > 0) throttle *= c.speed;

    return { throttle, steer, jump, boost, handbrake };
  }
}

