import { createRequire } from 'node:module';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(require('fs').readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + require('fs').readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch({ ...config.browser.launchOptions, headless: false, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });

await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForFunction(() => window.__game?.ready, null, { timeout: 30000 });
console.log('ready', await page.evaluate(() => window.__game.mode));

await page.click('#play-btn');
await page.waitForTimeout(1500);
let state = await page.evaluate(() => ({
  mode: window.__game.mode,
  score: window.__game.score,
  player: { x: window.__game.player.pos.x, y: window.__game.player.pos.y, z: window.__game.player.pos.z, boost: window.__game.player.boost },
  bot: { x: window.__game.bot.pos.x, z: window.__game.bot.pos.z },
  ball: { x: window.__game.ball.pos.x, y: window.__game.ball.pos.y, z: window.__game.ball.pos.z, speed: window.__game.ball.vel.length() },
  hint: document.getElementById('hint').className,
  countdown: document.getElementById('countdown').textContent,
}));
console.log('after start', JSON.stringify(state));

await page.keyboard.down('KeyW');
await page.keyboard.down('ShiftLeft');
await page.waitForTimeout(1200);
await page.keyboard.up('ShiftLeft');
await page.keyboard.up('KeyW');
state = await page.evaluate(() => ({
  mode: window.__game.mode,
  player: { x: window.__game.player.pos.x, z: window.__game.player.pos.z, boost: window.__game.player.boost, speed: window.__game.player.speed() },
  ball: { x: window.__game.ball.pos.x, z: window.__game.ball.pos.z, speed: window.__game.ball.vel.length() },
  hits: window.__game.player.stats.hits,
  camera: { x: window.__game.camera.position.x, y: window.__game.camera.position.y, z: window.__game.camera.position.z },
}));
console.log('after drive', JSON.stringify(state));

// force a ball hit
await page.evaluate(() => {
  const g = window.__game;
  g.setPlayer({ x: 0, z: 10, yaw: 0, vx: 0, vz: -20 });
  g.setBall({ x: 0, y: 1.82, z: 5.5, vx: 0, vy: 0, vz: 0 });
});
await page.waitForTimeout(500);
console.log('after forced hit', JSON.stringify(await page.evaluate(() => ({
  ball: { x: window.__game.ball.pos.x, z: window.__game.ball.pos.z, speed: window.__game.ball.vel.length() },
  hits: window.__game.player.stats.hits,
}))));

// score goal 1
await page.evaluate(() => window.__game.setBall({ x: 0, y: 2, z: -45, vx: 0, vy: 0, vz: -20 }));
await page.waitForTimeout(500);
console.log('goal1', JSON.stringify(await page.evaluate(() => ({
  mode: window.__game.mode,
  score: window.__game.score,
  banner: document.getElementById('goal-banner').className,
  bannerWho: document.querySelector('#goal-banner .who').textContent,
}))));
await page.evaluate(() => window.__game.finishGoal());
await page.waitForTimeout(400);
console.log('kickoff', JSON.stringify(await page.evaluate(() => ({ mode: window.__game.mode, count: document.getElementById('countdown').textContent }))));
await page.evaluate(() => window.__game.skipKickoff());
await page.waitForTimeout(600);
console.log('play2', JSON.stringify(await page.evaluate(() => ({ mode: window.__game.mode, count: document.getElementById('countdown').textContent }))));

// goal 2 and 3
for (let i = 0; i < 2; i++) {
  await page.evaluate(() => { window.__game.forceGoal(true); });
  await page.waitForTimeout(300);
  if (i === 0) {
    await page.evaluate(() => window.__game.finishGoal());
    await page.waitForTimeout(300);
    await page.evaluate(() => window.__game.skipKickoff());
    await page.waitForTimeout(400);
  }
}
await page.waitForTimeout(500);
console.log('end', JSON.stringify(await page.evaluate(() => ({
  mode: window.__game.mode,
  score: window.__game.score,
  title: document.getElementById('result-title').textContent,
  resultHidden: document.getElementById('result').classList.contains('hidden'),
  stats: {
    speed: document.getElementById('stat-speed').textContent,
    hits: document.getElementById('stat-hits').textContent,
    time: document.getElementById('stat-time').textContent,
  },
}))));

await page.click('#rematch-btn');
await page.waitForTimeout(400);
console.log('rematch', JSON.stringify(await page.evaluate(() => ({ mode: window.__game.mode, score: window.__game.score, hidden: document.getElementById('result').classList.contains('hidden') }))));

console.log('errors', errors);
await browser.close();

