import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(require('fs').readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + require('fs').readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: false });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('console', (m) => console.log('PAGE', m.type(), m.text()));
page.on('pageerror', (e) => console.log('PAGEERR', e.message));
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForFunction(() => window.__game?.ready);
console.log('ready. mode=', await page.evaluate(() => window.__game.mode));
await page.click('#play-btn');
await page.waitForTimeout(900);
console.log('after click. mode=', await page.evaluate(() => window.__game.mode));
console.log('camera=', await page.evaluate(() => JSON.stringify(window.__game.camera.position)));
console.log('menu hidden=', await page.evaluate(() => document.getElementById('menu').className));
// freeze without showing pause overlay
await page.evaluate(() => {
  window.__game.mode = 'paused';
  document.getElementById('pause').classList.add('hidden');
});
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/opencode/screens/diag3-full.png' });
const shot = async (name) => page.screenshot({ path: `/tmp/opencode/screens/diag3-${name}.png` });

// Hide boost pad visuals only (not groups? groups named boost-pad)
await page.evaluate(() => { window.__game.scene.traverse(n => { if (n.name === 'boost-pad') n.visible = false; }); });
await page.waitForTimeout(500); await shot('no-pads');

// Re-show pads, hide point lights
await page.evaluate(() => {
  window.__game.scene.traverse(n => { if (n.name === 'boost-pad') n.visible = true; });
  window.__game.scene.traverse(n => { if (n.isPointLight) n.visible = false; });
});
await page.waitForTimeout(500); await shot('no-pointlights');

await browser.close();

