163:     const hSpeed = Math.hypot(this.vel.x, this.vel.z);
164:     if (hSpeed > 0.1) {
165:       this.spinAxis.set(this.vel.z, 0, -this.vel.x).normalize();
166:       this.spinSpeed = hSpeed / BALL_RADIUS;
167:       this.mesh.rotateOnWorldAxis(this.spinAxis, this.spinSpeed * dt * 0.55);
168:     }
169:     this.halo.material.opacity = 0.22 + Math.sin(performance.now() * 0.003) * 0.04 + clamp(speed / 120, 0, 0.12);
170: 
171:     if (particles) {
172:       this.trailClock += dt;
173:       const interval = speed > 26 ? 0.022 : 0.04;
174:       while (this.trailClock > interval) {
175:         this.trailClock -= interval;
176:         const tint = new THREE.Color(Math.random() < 0.25 ? 0x6fe8ff : 0xe8fdff);
177:         particles.spawn({
178:           position: this.pos.clone().add(new THREE.Vector3(rand(-1, 1), rand(-1, 1), rand(-1, 1)).multiplyScalar(0.9)),
179:           velocity: new THREE.Vector3(rand(-0.7, 0.7), rand(-0.2, 1.1), rand(-0.7, 0.7)),
180:           color: tint,
181:           size: rand(0.3, 0.7),
182:           life: rand(0.25, 0.55),
183:           gravity: 1.2,
184:           drag: 1.4,
185:           grow: 1.2,
186:           fade: 1.5,
