188:       }
189:     }
190:   }
191: 
192:   collideCar(car) {
193:     if (Math.abs(this.pos.y - car.pos.y) > 2.5) return 0;
194: 
195:     const dx = this.pos.x - car.pos.x;
196:     const dz = this.pos.z - car.pos.z;
197:     const cos = Math.cos(car.yaw);
198:     const sin = Math.sin(car.yaw);
199:     const localX = dx * cos - dz * sin;
200:     const localZ = dx * sin + dz * cos;
201:     const halfW = 1.05;
202:     const halfL = 2.08;
203:     const cx = clamp(localX, -halfW, halfW);
204:     const cz = clamp(localZ, -halfL, halfL);
205:     const cy = clamp(this.pos.y - car.pos.y, -0.58, 0.72);
206: 
207:     const worldX = car.pos.x + cx * cos + cz * sin;
208:     const worldZ = car.pos.z - cx * sin + cz * cos;
209:     const worldY = car.pos.y + cy;
210: 
211:     let nx = this.pos.x - worldX;
212:     let ny = this.pos.y - worldY;
213:     let nz = this.pos.z - worldZ;
214:     let dist = Math.hypot(nx, ny, nz);
215: 
216:     if (dist > BALL_RADIUS) return 0;
217:     if (dist < 0.0001) {
218:       nx = 0; ny = 1; nz = 0; dist = 0.0001;
219:     }
220:     nx /= dist; ny /= dist; nz /= dist;
221: 
222:     const penetration = BALL_RADIUS - dist;
223:     this.pos.x += nx * penetration;
224:     this.pos.y += ny * penetration;
225:     this.pos.z += nz * penetration;
226: 
227:     const relX = this.vel.x - car.vel.x;
228:     const relY = this.vel.y - car.vel.y;
229:     const relZ = this.vel.z - car.vel.z;
230:     const vn = relX * nx + relY * ny + relZ * nz;
231:     if (vn >= 0) return 0;
232: 
233:     const impact = -vn;
234:     const power = 1.42;
235:     this.vel.x += nx * impact * power + car.vel.x * 0.22;
236:     this.vel.y += ny * impact * power + car.vel.y * 0.1;
237:     this.vel.z += nz * impact * power + car.vel.z * 0.22;
238: 
239:     // A little lift when catching the ball with the nose or roof.
240:     const carSpeed = car.speed();
241:     this.vel.y += clamp(carSpeed * 0.1 + impact * 0.06, 0, 5.5);
242: 
243:     // Keep the ball from being pinched through the car.
244:     if (Math.hypot(this.pos.x - car.pos.x, this.pos.z - car.pos.z) < 2.4) {
245:       const awayX = this.pos.x - car.pos.x;
246:       const awayZ = this.pos.z - car.pos.z;
247:       const len = Math.hypot(awayX, awayZ) || 1;
248:       this.vel.x += (awayX / len) * impact * 0.25;
249:       this.vel.z += (awayZ / len) * impact * 0.25;
250:     }
251: 
252:     car.vel.multiplyScalar(clamp(1 - impact * 0.006, 0.88, 1));
253:     car.stats.hits += 1;
254:     this.spinSpeed += impact;
255: 
256:     const speed = this.vel.length();
257:     if (speed > 62) this.vel.multiplyScalar(62 / speed);
258:     return impact;
259:   }
260: }

