page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
const log = (...a) => console.log(...a);
const state = () => page.evaluate(() => ({
  mode: window.__game.mode,
  score: window.__game.score,
  title: document.getElementById('result-title').textContent,
  resultHidden: document.getElementById('result').classList.contains('hidden'),
  stats: {
    speed: document.getElementById('stat-speed').textContent,
    hits: document.getElementById('stat-hits').textContent,
    time: document.getElementById('stat-time').textContent,
  },
  playerHits: window.__game.player.stats.hits,
  topSpeed: Math.round(window.__game.player.stats.topSpeed),
}));

await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForFunction(() => window.__game?.ready, null, { timeout: 30000 });
log('ready', await page.evaluate(() => window.__game.mode));
await page.click('#play-btn');
await page.waitForTimeout(1200);

// Real driving action.
await page.keyboard.down('KeyW');
await page.keyboard.down('ShiftLeft');
await page.waitForTimeout(1500);
await page.screenshot({ path: '/tmp/opencode/screens/action-desktop.png' });
await page.keyboard.up('ShiftLeft');
await page.keyboard.up('KeyW');
await page.waitForTimeout(300);
log('after drive', JSON.stringify(await state()));

// Force a real nose hit so stats register.
await page.evaluate(() => {
  const g = window.__game;
  g.setPlayer({ x: 0, z: 10, yaw: 0, vx: 0, vz: -22 });
  g.setBall({ x: 0, y: 1.82, z: 5.8, vx: 0, vy: 0, vz: 0 });
});
await page.waitForTimeout(700);
log('after hit', JSON.stringify(await state()));

// Goal 1 (also capture the celebration view).
await page.evaluate(() => window.__game.forceGoal(true));
await page.waitForTimeout(900);
await page.screenshot({ path: '/tmp/opencode/screens/goal-celebration.png' });
log('goal1', JSON.stringify(await state()));
await page.evaluate(() => window.__game.finishGoal());
await page.waitForTimeout(500);
await page.evaluate(() => window.__game.skipKickoff());
await page.waitForTimeout(1200);
log('play2', JSON.stringify(await state()));

// Goal 2.
await page.evaluate(() => window.__game.forceGoal(true));
await page.waitForTimeout(400);
await page.evaluate(() => window.__game.finishGoal());
await page.waitForTimeout(500);
await page.evaluate(() => window.__game.skipKickoff());
await page.waitForTimeout(1200);

// Goal 3 -> match over after goal timer.
await page.evaluate(() => window.__game.forceGoal(true));
await page.waitForTimeout(3600);
log('after third goal', JSON.stringify(await state()));
await page.screenshot({ path: '/tmp/opencode/screens/result-victory.png' });

// Rematch.
await page.click('#rematch-btn');
await page.waitForTimeout(1000);
log('rematch', JSON.stringify(await state()));

// Three bot goals -> defeat.
for (let i = 0; i < 3; i += 1) {
  await page.evaluate(() => window.__game.forceGoal(false));
  await page.waitForTimeout(400);
  if (i < 2) {
    await page.evaluate(() => window.__game.finishGoal());
    await page.waitForTimeout(500);
    await page.evaluate(() => window.__game.skipKickoff());
    await page.waitForTimeout(1200);
  }
}
await page.waitForTimeout(3600);
log('after bot goals', JSON.stringify(await state()));
await page.screenshot({ path: '/tmp/opencode/screens/result-defeat.png' });

// Back to menu.
await page.click('#menu-btn');
await page.waitForTimeout(1200);
log('menu', JSON.stringify(await page.evaluate(() => ({ mode: window.__game.mode, menuHidden: document.getElementById('menu').classList.contains('hidden'), inMatch: document.body.classList.contains('in-match') }))));
log('errors', errors);
await browser.close();

